(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fy"] = {"ui":{"skip":"Gean nei de ynhâld","back":"← Werom nei AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies in taal","lang.search":"Taal sykje","lang.none":"Gjin taal fûn","lang.notYet":"{name} is noch net oersetten","theme.aria":"Tema wikselje: ljocht, tsjuster of swart","theme.toLight":"Wikselje nei ljocht tema","theme.toDark":"Wikselje nei tsjuster tema","theme.toBlack":"Wikselje nei swart tema (echt swart, sêft foar OLED-skermen)","words.underline":"Dizze wurden op 'e side ûnderstreekje","words.underlineHelp":"Hâld de mûs boppe in stippele wurd of tik derop om te sjen wat it betsjut.","words.col.todo":"Kaarten dy't foar no keazen binne: it team begjint dêrmei as folgjende.","words.col.doing":"In AI is no oan dizze kaart dwaande.","words.col.review":"Ien AI hat it wurk dien; in oare kontrolearret it foardat it by dy komt.","words.col.verify":"Wachtet op dy: probearje it út en sis oft it wurket.","words.col.team":"Dyn notysjes of antwurden, wachtsjend dat it team se oppakt.","words.col.done":"Klear en goedkard.","index.title":"AI-gile: dyn AI-ûntwikkelteam, op ien boerd","index.description":"AI-gile is in kanbanboerd foar AI-koadeteams. Se wurkje wylst do sliepst; do krijst ien koarte steapel mei dingen om te beslissen, te testen en te akseptearjen.","hero.logoAlt":"AI-gile-boerdikoan","hero.h1.html":"Dyn AI-ûntwikkelteam, op ien&nbsp;boerd.","hero.alpha":"🐣 Sletten pre-alfa","hero.alphaTitle":"Betiid en net ôf: tank dat do it besiket!","hero.lede":"Se bouwe wylst do sliepst. Do wurdst wekker mei ien koarte steapel: in pear fragen, in pear dingen om te testen, in pear pearse diamanten. Klik, akseptearre, werom nei dyn kofje.","dl.windows":"Windows-app","dl.browser":"Brûk it yn dyn browser","dl.messenger":"📱 Messenger foar dyn telefoan","dl.soon":"Komt gau","dl.notify":"🔔 Lit my witte as it iepengiet","dl.notifySmall":"Alfa of beta","hero.secondary":"Agile, mar it team hat nea in stânkofje nedich. (Se hâlde de stânddei-oerlis dochs.)","pitch.h2":"AI-gile yn safolle wurden as do wolst","pitch.lede":"Kies in lingte, fan ien wurd oant 144. Elke lingte is in eigen beskriuwing, skreaun foar dy maat. Sleep de skowler of brûk de pylktoetsen.","pitch.rangeLabel":"Lingte yn wurden","pitch.dice":"🎲 in oare ferzje","pitch.words.one":"{n} wurd","pitch.words.other":"{n} wurden","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} teken","pitch.chars.other":"{n} tekens","count.line.html.one":"{n} kaart op it boerd op dit stuit","count.line.html.other":"{n} kaarten op it boerd op dit stuit","people.humans.html.one":"👥 {n} minske","people.humans.html.other":"👥 {n} minsken","people.agents.html.one":"🤖 {n} agint","people.agents.html.other":"🤖 {n} aginten","people.working.html.one":"⚡ {n} oan it wurk op dit stuit","people.working.html.other":"⚡ {n} oan it wurk op dit stuit","pre.title":"AI-gile: hjir wurdt wat boud","pre.description":"Hjir wurdt wat boud. In boerd dêr't AI-teams bouwe wat do freegest, en dy ûnderweis wat leare. Foar no in sletten pre-alfa mei freonen.","pre.h1":"Hjir wurdt wat boud. 🤫","pre.line":"In boerd dêr't AI-teams bouwe wat do freegest, en dy ûnderweis wat leare. Foar no in sletten pre-alfa mei freonen.","pre.btn":"🔔 Lit my witte as it iepengiet","pre.peek":"Efter it glês: it echte boerd, live. Elke kaart is in kleurde balke.","pre.peekFake":"Efter it glês: sa sjocht in boerd oan it wurk der út.","pre.night":"🌙 De nachtwachter hat it roer yn hannen · 😴 de minske rêstet","features.aria":"Wat it docht","f.pile.h":"Ien steapel foar dy","f.pile.html":"<b>Foar dy</b> hat alles wat op dy wachtet, oer alle projekten hinne: fragen, dingen om te testen, taken dy't allinnich in minske dwaan kin. Dyn wachtrige seit wat folget en hoe lang it duorret.","f.sleep.h":"Teams dy't wurkje wylst do sliepst","f.sleep.p":"Elk projekt hat in lieder en in team fan AI-aginten. Kommentearje op in kaart en it team wurdt wekker, docht it wurk en jout it werom mei stappen dy't ek in wurch minske folgje kin.","f.tester.h":"In AI-tester kontrolearret earst","f.tester.p":"Foardat der wat by dy komt, folget in tester de stappen yn in kopy fan de app en lit sjen wat er seach, mei in skermôfbylding. Blêdzje troch de slagge kaarten en akseptearje mei ien klik.","f.proof.h":"Bewiis, gjin beloften","f.proof.p":"Elke oerdracht lit sjen wat feroare is: de bestannen, de diff, de skermôfbyldingen. Net elke app iepenmeitsje om te sjen oft it klear is.","f.chat.h":"Praat mei dyn lieders","f.chat.p":"In Discord-eftige balke: ien ikoan per projekt, pearse diamanten foar wat dy nedich hat. Stjoer in lieder in idee; hy makket der kaarten en in plan fan, mei in ✅ Go-knop.","f.tidy.h":"Hâldt himsels oarderlik","f.tidy.p":"Besibbe kaarten smelte ta ien, wazige titels wurde rjochte, en in tokenkontrôle hâldt de koade licht. Minder om tusken te wikseljen, minder om oan te tinken.","f.private.h":"Fan dy, op dyn kompjûter","f.private.li1":"It boerd rint op dyn eigen masine en antwurdet allinnich dy.","f.private.li2":"Priveeberjochten tusken minsken binne end-to-end fersifere.","f.private.li3":"Gjin akkounts, gjin trackers, gjin cookies.","f.lang.h":"Yn dyn taal","f.lang.p":"Mear as 120 talen, fan Nederlânsk, Welsk en Japansk oant piraat, Yoda en Klingon, mei in flugge wiksel werom nei Ingelsk foar de fakwurden.","f.service.h":"Fan in idee nei in echte tsjinst","f.service.p":"Mei AI wat boud dat minsken no brûke? Markearje it as tsjinst en it boerd helpt dy it goed draaiende te hâlden: beskikberenskontrôles, in iepenbiere statusside, incidinten mei in ferslach, wizigingen dy't in Go nedich hawwe, en reservekopyen dy't alle dagen kontrolearre wurde. Help lit dy ûnderweis elke stap sjen.","msgr.h2":"AI-gile Messenger: dyn team yn dyn bûse","msgr.p1":"Praat mei dyn AI-team sûnder it boerd iepen te dwaan. Chat mei dyn projektlieders en dyn freonen, en sjoch de teststappen fan in kaart en beantwurdzje se, allegear fan dyn telefoan ôf.","msgr.p2":"Om him te keppeljen, scan in QR-koade op dyn boerd. Earste kear? In freonlike demochat lit dy alles sjen.","msgr.when":"Earst Android, dêrnei in webferzje foar telefoans en iPhone.","msgr.who":"Dyn projektlieder","msgr.b1":"De oplossing foar de donkere modus is klear. Wolst de teststappen hawwe?","msgr.b2":"Ja, graach!","msgr.b3":"1. Iepenje Ynstellings. 2. Kies Donker. Sjocht it der goed út?","tl.aria":"Tiidline fan it earste petear oant de roadmap","tl.h2":"Fan it earste petear oant wat folget","tl.lede":"Echte datums en tiden, yn dyn eigen tiidsône. Nei hjoed is it it plan, sûnder tasein datums.","tl.today":"Hjoed","tl.planned":"pland","tl.doing":"dwaande","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarten","join.h2":"Doch mei","join.lede":"AI-gile wurdt boud troch in nuvere snaak mei in burd, AuDHD en in pear striden mei de mentale sûnens, en troch in grut tal geduldige aginten. It is foarearst privee, in sletten alfa mei freonen. Wolst it besykje as it iepengiet?","join.btn":"Meld dyn belangstelling","join.small":"Wy mailje dy, mear net","footer.tag":"AI-gile. Gjin trackers, gjin cookies, gjin stânkofje.","footer.licence":"Bedriuwslisinsje","footer.status":"Status","footer.privacy":"Wat wy bewarje","footer.thanks":"Gesprekken mei tank oan ChilledChat","form.sending":"Ferstjoere…","form.failed":"Dat slagge net: besykje it letter wer.","form.offline":"Koe AI-gile net berikke: besykje it letter wer.","form.keep":"Wy brûke dit allinnich om dy te antwurdzjen, dêrnei wiskje wy it. Gjin trackers, gjin cookies.","form.keepLink":"Wat wy bewarje","interest.title":"AI-gile: lit my witte as de alfa iepengiet","interest.description":"Lit dyn e-mailadres efter om te hearren wannear't de sletten alfa of beta fan AI-gile iepengiet.","interest.h1":"🔔 Lit my witte as it iepengiet","interest.lede":"AI-gile sit yn sletten pre-alfa. Lit dyn e-mailadres efter en wy skriuwe ien kear, as der in plak foar dy is.","interest.email":"Dyn e-mailadres","interest.which":"Hokker test?","interest.alpha":"Sletten alfa: betiid, rûch, in soad feroarings","interest.beta":"Beta: stabiler, letter","interest.both":"Beide, wat earst komt","interest.submit":"Set my op de list","interest.thanks":"Tank! Do stiest op de list.","licence.title":"AI-gile: bedriuwslisinsje","licence.description":"AI-gile brûke yn dyn bedriuw? Freegje in fergese bedriuwslisinsje oan.","licence.h1":"📜 Bedriuwslisinsje","licence.lede":"AI-gile brûke op it wurk? Fertel ús wa't do bist en wat do dochst. As it wat goeds docht, is de lisinsje fergees.","licence.company":"Bedriuw","licence.website":"Webside","licence.what":"Wat do dochst","licence.how":"Hoe't it de wrâld helpt","licence.email":"E-mail","licence.submit":"Oanfreegje","licence.thanks":"Tank! Wy antwurdzje per e-mail.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles stil","status.intro":"Wurket AI-gile no? Dizze side kontrolearret elke 5 minuten de webside, it dielen fan boerden, oproppen en de download.","status.up":"Wurket (antwurde yn {ms} ms)","status.slow":"Antwurde net by de lêste kontrôle, besiket it wer","status.down":"Plat: antwurde net by de lêste twa kontrôles","status.svc.web":"Webside","status.svc.web.offers":"Dizze side: wat AI-gile is, en it belangstellingsformulier","status.svc.boards":"Boerden diele","status.svc.boards.offers":"Iepenbiere boerden, berjochten tusken freonen en útnoegings","status.svc.calls":"Oproppen","status.svc.calls.offers":"Lûd, fideo en skerm diele yn AI-gile","status.svc.download":"Download","status.svc.download.offers":"De Windows-ynstallaasje en útnoegingskeppelings","status.checking":"Kontrolearje…","status.offline":"Kin de statustsjinst no net berikke (besykje it wer)","status.updated":"bywurke {ago}","status.justNow":"krekt no","status.min":"{n} min lyn","status.hours":"{n} oere lyn","status.days":"{n} d lyn","privacy.title":"AI-gile: wat wy bewarje","privacy.h1":"Wat wy bewarje","privacy.lede":"Koartsein: allinnich wat do ús stjoerst, en net lang.","privacy.only":"Allinnich wat do ús stjoerst: wat do yn in formulier typst, lykas dyn e-mailadres. Fierder neat oer dy.","privacy.sealed":"It wurdt fersegele, sadat ús server it net lêze kin: yn dyn browser, foardat it fuortgiet (by in âldere browser, op it momint dat it oankomt). Allinnich ús eigen boerd kin it iepenje.","privacy.server":"It wurdt fan 'e server wiske sa gau as it ús boerd berikt. Wat der nei 30 dagen noch stiet, wurdt dochs wiske.","privacy.board":"Wy bewarje it op ús boerd allinnich oant wy dy antwurde ha, dêrnei wiskje wy it dêr ek.","privacy.none":"Gjin trackers, gjin cookies, gjin analytics.","privacy.local":"Dyn taal en dyn kar foar ljocht of tsjuster bliuwe yn dyn eigen browser. Se wurde nea nei ús stjoerd.","privacy.ask":"Wolsto dat it earder fuort is? Antwurdzje op ús e-mail en sis it mar.","live.h2":"Sjoch it boud wurde, live","live.caption":"Elke kaart is ferburgen: do sjochst de foarm fan it wurk, net de wurden.","live.watching.one":"live: {n} sjocht","live.watching.other":"live: {n} sjogge","live.last.now":"Lêste kaart krekt ferpleatst","live.last.min.one":"Lêste kaart {n} min lyn ferpleatst","live.last.min.other":"Lêste kaart {n} min lyn ferpleatst","live.last.hour.one":"Lêste kaart {n} oere lyn ferpleatst","live.last.hour.other":"Lêste kaart {n} oeren lyn ferpleatst","live.last.day.one":"Lêste kaart {n} dei lyn ferpleatst","live.last.day.other":"Lêste kaart {n} dagen lyn ferpleatst","live.offline":"It live-boerd nimt efkes in azem. Sjoch gau wer.","live.cols":"Backlog|Te dwaan|Dwaande|Team kontrolearret|Foar dy om te test|Foar it team|Klear","footer.models":"AI-gile lit AI-modellen foar dy rinne. Wat se sizze en dogge is fan harren, kontrolearje it dus foardat do it fertroust.","privacy.ai.h":"It AI-diel","privacy.ai.models":"AI-gile is it boerd. It wurk wurdt dien troch AI-modellen fan oare bedriuwen, lykas Claude, Codex en Gemini, op dyn eigen accounts.","privacy.ai.check":"Wat se skriuwe en dogge komt fan harren, en it kin ferkeard wêze. Kontrolearje it foardat do derop fertroust of it útbringst.","privacy.ai.files":"Se feroarje bestannen en fiere kommando's út yn de mappen dy't do keppelest. Meitsje in reservekopy.","privacy.ai.send":"Wat do in model joust giet nei it bedriuw dat it draait, ûnder harren betingsten. De eigen betingsten en kosten fan elk bedriuw jilde.","privacy.ai.asis":"AI-gile is in iere testferzje, jûn sa't it is."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegearre."]},{"n":2,"texts":["Robots wurkje.","Aginten, oarderlik.","Ideeën, boud."]},{"n":3,"texts":["Kanban foar robots.","Ideeën wurde funksjes.","Fergees agintkanban."]},{"n":5,"texts":["Kanbanboerd rinne troch aginten.","Do skriuwst, aginten bouwe.","Fergees, lokaal, getest, in bytsje gek."]},{"n":8,"texts":["In fergees kanbanboerd dêr't AI-aginten wurkje.","Skriuw in idee. Aginten bouwe it. Do aksepteart.","Agile foar ien minske en in soad geduldige robots."]},{"n":13,"texts":["In kanbanboerd op dyn kompjûter dêr't AI-aginten de kaarten oppakke en útfiere.","Skriuw in idee. In team fan aginten bout it. In tester kontrolearret it.","Fergees, gjin akkounts, gjin trackers: in boerd, in pear robots, en do as baas."]},{"n":21,"texts":["AI-gile is in kanbanboerd om mei AI-koadeaginten te wurkjen. Se pakke de kaarten op; do test se en aksepteart se.","Elk projekt krijt in lieder en in team fan AI-aginten. Kommentearje op hokker kaart ek en it team giet oan it wurk.","In fergees, persoanlik taakboerd dat op dyn eigen kompjûter rint. De wurkers binne robots. Dejinge dy't ja seit, bist do."]},{"n":34,"texts":["Do set ideeën op in boerd. In team fan AI-aginten makket der wurkjende funksjes fan, test se en jout se werom mei stappen om út te probearjen. Neat telt as klear oant do it seist.","AI-gile is in selsmakke kanbanboerd dat Rich boude mei in soad help fan de aginten dy't it no beheart. It is fergees, rint op dyn kompjûter en wurdt mei freonen dield, net ferkocht.","Stel dy in gewoan kanbanboerd foar, mei kolommen fan Backlog oant Klear, útsein dat de kaarten oppakt wurde troch AI-aginten. Se melde foarútgong, stelle fragen as se fêst sitte, en wachtsje altyd op dyn tommen omheech."]},{"n":55,"texts":["AI-gile is in kanbanboerd wêrfan it team út AI-aginten bestiet. Elk projekt hat in lieder dy't it wurk plant en helpers dy't it bouwe. As in funksje klear is, besiket in AI-tester it út en makket in skermôfbylding, dan komt it op dyn steapel telâne. Akseptearje it, of kommentearje en se wurkje it nei.","It begûn as ien minske syn manier om in soad AI-koadesesjes tagelyk by te hâlden, en groeide út ta in echt boerd. It rint op dyn masine, hat gjin akkount nedich en hat gjin trackers. It is fergees foar freonen en nijsgjirrigen. It is ek net ôf, dus rekkenje op rûge rânen en no en dan in ferrassing.","Dit is de earlike ferzje. Do moatst noch altyd de ideeën hawwe, en do moatst de resultaten noch altyd kontrolearje. Wat AI-gile docht is alles dêrtusken: it hâldt de kaarten op oarder, wekket de krekte agint as do kommentearrest, lit presys sjen wat feroare is, en set it alles op ien koarte steapel foar dy."]},{"n":89,"texts":["AI-gile is in fergees kanbanboerd dat do op dyn eigen kompjûter rinne litst. Yn plak fan minsken hat elk projekt in team fan AI-aginten: in lieder dy't dyn ideeën omsette yn kaarten en in plan, en helpers dy't de kaarten yn folchoarder fan wichtichheid oppakke. As der wat boud is, folget in AI-tester de teststappen en lit dy sjen wat er seach. Dan wachtet it op ien steapel mei de namme Foar dy. Do aksepteart it, of do kommentearrest en it team besiket it noch ris. Neat komt ea by Klear sûnder dy.","Inkelde funksjes dy't do miskien net ferwachtest. In nachtwacht hâldt de kolom Te dwaan fol wylst do sliepst, mei kaarten dêr't gjin antwurd fan dy foar nedich is. In tokenteller lit sjen hoefolle de aginten hjoed en dizze wike brûkt hawwe, en de Gjin-token-modus seit harren dat se ophâlde moatte mei útjaan. Do kinst freonen berjochten stjoere, en priveeberjochten binne end-to-end fersifere. It boerd praat sa'n 120 talen, ûnder oaren Nederlânsk, Flaamsk, piraat en Klingon. Neat dêrfan kostet in sint, en gjinien besiket it dy oan te smeren.","AI-gile is in lyts, persoanlik projekt, gjin bedriuw. Rich woe foar ferskate AI-koadeprojekten soargje sûnder elke app iepen te dwaan om te sjen hoe't it derfoar stie, dus hy en de aginten boude dêr in boerd foar, en brûkten it boerd doe om de rest sels te bouwen. It sit yn sletten pre-alfa, wat betsjut dat it wurket, foar it grutste part, foar in hânfol freonen. Der is gjin prizenside, gjin nijsbrief en gjin groeiplan. As it nuttich klinkt, kinst freegje om it út te probearjen as it wat fierder iepengiet."]},{"n":144,"texts":["AI-gile is in kanbanboerd foar ien minske en in soad AI-aginten. It rint op dyn eigen kompjûter en is folslein fergees. Do foegest projekten ta, en elk projekt krijt in lieder en in lyts team. Do praatst mei de lieder, in bytsje as op Discord, en beskriuwst in idee; de lieder makket der kaarten en in plan fan, en wachtet dan oant do op Go drukst. It team wurket de kaarten ôf op folchoarder fan wichtichheid, mei in ienfâldige kommandorigel makke foar taalmodellen. Foardat der wat by dy weromkomt, folget in AI-tester de stappen yn in kopy fan de app en foeget in skermôfbylding ta. Klear wurk komt op dyn steapel mei de feroare bestannen en de diff. Do aksepteart it, of do litst in kommentaar efter en it team wurdt wekker en besiket it opnij. Allinnich do kinst in kaart nei Klear ferpleatse.","In dei mei AI-gile, rûchwei. Jûns litst in pear kommentaren efter: dizze knop stiet op it ferkearde plak, dy list moat sortearre wurde, koe der ek in tsjuster tema komme. Do giest op bêd. De aginten lêze de kommentaren, meitsje de feroarings, testen se en jouwe se werom. As Te dwaan leech rekket, folt de nachtwacht it út de backlog oan mei kaarten dêr't gjin antwurd fan dy foar nedich is. Moarns leit der ien koarte steapel: in pear fragen en in pear dingen om út te probearjen, elk mei stappen dy't in sliepeachtich minske folgje kin en in skermôfbylding fan it wurkjen. Do klikst der troch, aksepteart de goede en stjoerst de rest werom. In tokenteller lit sjen wat it allegear brûkt hat, en de Gjin-token-modus is der foar de mager wiken. Dan ytst dyn moarnsiten, dêr't de aginten noch net mei helpe kinne.","Earst, wat AI-gile net is. It is gjin startup, it is net te keap, en gjinien sammelet dyn gegevens. It is in fergees boerd dat op dyn kompjûter rint, sûnder akkounts, sûnder trackers en sûnder cookies. Wat it wol is: ien oarderlike plak om alle AI-koadeprojekten tagelyk te sjen, mei in team fan aginten dat de kaarten docht en do dy de besluten nimst. It smelt besibbe kaarten gear, makket wazige titels goed, en hâldt yn de gaten hoe licht de koade bliuwt. It praat sa'n 120 talen, fan Nederlânsk en Flaamsk oant piraat en Klingon. Freonen kinne inoar berjochten stjoere, privee en fersifere. It is boud troch Rich en in grut tal geduldige aginten, meast troch himsels te brûken. It sit yn sletten pre-alfa, dus it is op plakken noch rûch. As it dy leuk klinkt, freegje it freonlik en miskien komst der betiid yn."]}],"quips":{"1":"Ien wurd. Dryst. Miskien te dryst.","3":"Trije wurden. Al earliker as de measte produktsiden.","8":"Acht wurden. Noch koarter as in stânddei-oerlis.","21":"De lingten binne trouwens story points. Fansels binne se dat.","55":"Fiifenfyftich wurden. Twa kaarten binne klear wylst do dit lies.","144":"Dat is de lange. Der is gjin 233. De aginten binne op bêd."}},"timeline":{"first-idea.name":"It earste idee","first-idea.line":"It allereerste petear, foardat der ien rigel koade wie.","first-board.name":"Earste boerd","first-board.line":"In boerd dat syn eigen bou byhâldt: kaarten, kolommen, slepe en delsette, projekten.","team-roles.name":"Team en rollen","team-roles.line":"Agintprofilen, teamsjablonen, romtes en wa't wat docht.","install.name":"Ynstallaasje en útjeften","install.line":"In zip dy't in freon ynstallearje kin, selsbywurkjen, kanalen en weromdraaie.","usage-saver.name":"Gebrûksbesparring","usage-saver.line":"Mjit wat runs kostje, hâld de koade licht, bewarje dyn limyt.","friends.name":"Freonen en dielen","friends.line":"Priveeberjochten, in forskoft relay, útnoegingen, rollen en dielde projekten.","languages.name":"Talen","languages.line":"Elke skermtekst yn in taalbestân, mei Nederlânsk en Flaamsk earst.","ai-tester.name":"AI-tester","ai-tester.line":"In tester kontrolearret elke oerdracht earst en lit sjen wat er seach.","website.name":"De webside","website.line":"aigile.lol, de teaser en dizze tiidline.","streaming.name":"Chat en streamen","streaming.line":"Discord, Twitch, OBS, streamermodus, GIF's en emoji's.","no-ai.name":"Edysje sûnder AI","no-ai.line":"In boerd foar minsken dy't koadzje sûnder AI, en iepenbiere boerden.","night-watch.name":"Nachtwacht","night-watch.line":"In wachter en Scrum Master hâlde de teams op taak wylst do sliepst.","p-more.name":"Al it oare","p-more.line":"Lytsere ideeën dy't noch op har bar wachtsje.","p-android.name":"Tillefoan en Android","p-android.line":"Berik dyn boerd fan in tillefoan, dêrnei in eigen Android-app.","p-release.name":"Alfa en fierder","p-release.line":"Sletten alfa, de libbene side, dêrnei beta.","p-languages.name":"Mear talen","p-languages.line":"130 talen, en in ûnderdompelingsmodus foar wa't in taal leart.","p-engines.name":"Mear AI-motoren","p-engines.line":"Kies Claude, Codex, Gemini, Copilot of Cursor foar elke agint.","p-pro.name":"Profesjonele praktyk","p-pro.line":"Risikolabels, gearfoegingspoarten, ynsidintkaarten en leuningen.","p-self.name":"Soargje foar dy","p-self.line":"Wurch-modus, selssoarch-herinneringen en 4:20.","p-servers.name":"Servers en skaal","p-servers.line":"Globale serverynstellings, rollen en planne foar groei.","p-livestream.name":"Streamingekstra's","p-livestream.line":"Twitch-chat, eigen emoji's en in iepenbier live byld."},"words":{"button":"📖 Fakwurden","h":"📖 Wurden útlein","intro":"Fergees training yn gewoane taal: elk wurd dat do tsjinkomst fan in earste idee oant in tsjinst dêr’t minsken op fertrouwe, mei ûnderweis Agile, bouwen, it feilich en oan ’e gong hâlden en wurkjen mei AI.","search":"In wurd sykje…","none":"Gjin wurd dat hjirby past.","close":"Slute","count":{"one":"{count} wurd","other":"{count} wurden"},"groups":[{"id":"idea","name":"💡 Idee en ferkenning"},{"id":"plan","name":"🗺️ It wurk plannen"},{"id":"agile","name":"🔁 Agile wurkwizen"},{"id":"build","name":"🛠️ Bouwe"},{"id":"test","name":"🧪 Testen en kwaliteit"},{"id":"change","name":"🔀 Feilich feroarje"},{"id":"run","name":"🛎️ In tsjinst draaiende hâlde"},{"id":"sec","name":"🔒 Feiligens en privacy"},{"id":"ai","name":"🤖 Wurkje mei AI"},{"id":"money","name":"💰 Jild en lisinsjes"}],"list":[{"id":"discovery","g":"idea","word":"Ferkenning","text":"De earste faze, wêryn't do útfynst hokker probleem it wurdich is om op te lossen en foar wa, foardat der wat boud wurdt.","also":["ferkenningsfase"]},{"id":"problemstmt","g":"idea","word":"Probleemstelling","text":"Ien of twa sinnen dy’t sizze wa’t in probleem hat, wat it is en wêrom’t it fan belang is, sadat elkenien itselde doel foar eagen hat.","also":["probleemstellingen"]},{"id":"user","g":"idea","word":"Brûker","text":"In persoan dy't brûkt wat do bouwst. Syn behoeften binne wêrom't it wurk der is.","also":["brûkers"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Belanghawwende","text":"Elkenien dy’t belang hat by hoe’t it wurk útpakt of der troch rekke wurdt, lykas de minsken dy’t der foar betelje, it brûke of it stypje.","also":["belanghawwenden"]},{"id":"persona","g":"idea","word":"Persona","text":"In ferbeelde mar realistyske persoan dy't ien soart brûker fertsjintwurdiget, sadat it team freegje kin: “Soe Sam dit maklik fine?”","also":["persona’s"]},{"id":"userresearch","g":"idea","word":"Brûkersûndersyk","text":"Prate mei en sjen nei echte minsken om te learen wat se nedich hawwe, ynstee fan te rieden.","also":["brûkersinterviews"]},{"id":"journey","g":"idea","word":"Brûkersreis","text":"De stappen dy't in persoan nimt om wat dien te krijen, fan it earste hearren derfan oant it ôfrûnen, ek bûten dyn produkt. As do it tekenest, sjochst do wêr't er fêstrint.","also":["brûkersreizen","klantreis"]},{"id":"painpoint","g":"idea","word":"Pynpunt","text":"Wat minsken no argewaasje jout of ophâldt. Goeie produkten nimme pynpunten fuort.","also":["pynpunten"]},{"id":"assumption","g":"idea","word":"Oanname","text":"Wat do leaust, mar noch net kontrolearre hast. Oannames opskriuwe lit sjen wat do earst testen moatst.","also":["oannames"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypoteze","text":"In ferwachting dy’t do kontrolearje wolst, mei wat do tinkst dat der barre sil, lykas “minsken melde har oan as de earste moanne fergees is”.","also":["hypotezen"]},{"id":"experiment","g":"idea","word":"Eksperimint","text":"In lytse plande test om te learen oft in idee wurket, foardat do der folle op ynsetst.","also":["eksperiminten"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"In rap, rûch besykjen om te sjen oft in idee oerhaupt wurkje kin. It wurdt meastal fuortsmiten as do it antwurd hast.","also":["PoC","proof of concept","bewiis fan konsept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"In betiid model fan it produkt, faak plaatsjes om op te klikken, om it idee op minsken út te probearjen foardat do it goed bouwst.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"In ienfâldige skets fan in skerm dy't sjen lit wêr't dingen komme, sûnder kleuren of echte ynhâld.","also":["wireframes","triedmodel"]},{"id":"mockup","g":"idea","word":"Mockup","text":"In detaillearre ôfbylding fan hoe’t in skerm der útsjen sil, mei echte kleuren en tekst, mar der wurket noch neat.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"De redenen foar in projekt: wat it kostet, wat it opbringt of besparret, en de risiko’s.","also":["business cases","ûnderbouwing"]},{"id":"feasibility","g":"idea","word":"Haalberens","text":"Oft wat echt boud en ûnderhâlden wurde kin mei de tiid, it jild en de feardigens dy’t do hast.","also":["haalber","feasibility"]},{"id":"outcome","g":"idea","word":"Útkomst","text":"De feroaring dy’t do foar minsken wolst, lykas minder ôfspraken dy’t mist wurde. Dat is wichtiger as hoefolle do bouwst.","also":["útkomsten"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Wat it team makket, lykas in nij skerm of in rapport. It meitsjen derfan betsjut net automatysk dat it ien helpt.","also":["outputs","opbringst"],"noTip":1},{"id":"successmetric","g":"idea","word":"Súkseswearde","text":"In getal dat dy fertelt oft it wurk die wêr’t it foar bedoeld wie, lykas mear minsken dy’t harren bestelling ôfmeitsje.","also":["súkseswearden","success metric"]},{"id":"kpi","g":"idea","word":"Kaaiprestaasje-yndikator (KPI)","text":"In wichtich getal dat do yn de gaten hâldst om te sjen oft it goed giet, lykas oanmeldingen per wike.","also":["KPI","KPI’s","key performance indicator"]},{"id":"okr","g":"idea","word":"Doelen en kaairesultaten (OKR’s)","text":"In manier om doelen te stellen: it doel seit wat do wolst, en in pear kaairesultaten binne de getallen dy’t sjen litte dat do der kommen bist.","also":["OKR","OKRs","OKR’s"]},{"id":"product","g":"plan","word":"Produkt","text":"It ding dat boud en ûnderhâlden wurdt foar syn brûkers, lykas in app, in webside of in ark.","also":["produkten"],"noTip":1},{"id":"vision","g":"plan","word":"Produktfisy","text":"In koarte ferklearring oer wa’t it produkt helpt en wêr’t it op de lange termyn hinne giet.","also":["fisyferklearring"]},{"id":"po","g":"plan","word":"Produkteigener (PO)","text":"De persoan dy’t beslút wat der boud wurdt en yn hokker folchoarder, sadat it team altyd oan it wichtichste wurket. Yn AI-gile bist dat do.","also":["PO","produkteigeners"]},{"id":"pm","g":"plan","word":"Produktmanager (PM)","text":"De persoan dy’t soarget foar de rjochting fan in produkt: hokker problemen it oplost, foar wa en wêrom. PM kin ek projektmanager betsjutte, dus kontrolearje hokker.","also":["produktmanagers"]},{"id":"projmgr","g":"plan","word":"Projektmanager","text":"De persoan dy’t in projekt op tiid en binnen budzjet hâldt en byhâldt wa’t wat docht en foar wannear.","also":["projektmanagers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"In rûch plan fan wat der de kommende moannen oankomt, op folchoarder. It lit rjochting sjen, gjin krekte datums, en feroaret as do learst.","also":["roadmaps","paadkaart"]},{"id":"milestone","g":"plan","word":"Mylpeal","text":"In punt yn in projekt dat it wurdich is om te markearjen, lykas “earste ferzje live” of “100 brûkers”.","also":["mylpealen"]},{"id":"mvp","g":"plan","word":"Minimum libbensfetber produkt (MVP)","text":"De lytste ferzje fan in produkt dy’t noch hieltyd nuttich is foar echte minsken, sadat do betiid fan har leare kinst.","also":["MVP","MVP’s","minimum viable product"]},{"id":"requirement","g":"plan","word":"Eask","text":"Wat it klearmakke produkt dwaan of wêze moat.","also":["easken"],"noTip":1},{"id":"scope","g":"plan","word":"Omfang","text":"Wat by it wurk heart en, krekt sa wichtich, wat net.","also":["binnen it omfang","bûten it omfang"]},{"id":"scopecreep","g":"plan","word":"Omfangskrûp","text":"As der stik foar stik hieltyd mear oan it wurk tafoege wurdt, sûnder dat immen it iens wurdt oer de ekstra tiid of kosten, sadat it nea echt klear komt.","also":["funksjekrûp","scope creep"]},{"id":"feature","g":"plan","word":"Funksje","text":"Ien ding dat it produkt foar minsken dwaan kin, lykas “dyn wachtwurd weromsette”.","also":["funksjes"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"In grut stik wurk, te grut foar ien kear, dus it wurdt yn lytsere kaarten ferdield.","also":["epics"]},{"id":"story","g":"plan","word":"Brûkersferhaal","text":"In lyts stik wurk skreaun fan de kant fan de brûker: “As klant wol ik myn mandsje bewarje, sadat ik letter ôfrekenje kin.” It set in petear yn gong oer wat der boud wurde moat.","also":["brûkersferhalen"]},{"id":"ac","g":"plan","word":"Akseptaasjekritearia (AC)","text":"De kontrôles dy’t ien kaart trochstean moat om as klear te tellen, ôfpraat foardat it wurk begjint, lykas “it mandsje is der noch as ik útlogd en wer ynlogd haw”.","also":["akseptaasjekritearia"]},{"id":"task","g":"plan","word":"Taak","text":"In inkele klus dy’t dien wurde moat, faak ien lytse stap fan in grutter ferhaal.","also":["taken"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"In oar wurd foar in kaart: ien stik wurk of ien fersyk, folge fan begjin oant ein.","also":["tickets"]},{"id":"priority","g":"plan","word":"Prioriteit","text":"Hoe wichtich of driuwend wat is yn ferliking mei al it oare, sadat it wichtichste wurk earst giet.","also":["prioriteiten"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritearring","text":"It wurk op folchoarder fan belang sette. In bekende manier is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["prioritearje","MoSCoW"]},{"id":"estimate","g":"plan","word":"Skatting","text":"In gissing fan hoe grut of hoe lang in stik wurk is. It is in gissing, gjin belofte.","also":["skattings","skatte"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"In manier om de grutte fan wurk te rieden troch kaarten mei inoar te fergelykjen (“likernôch twa kear sa grut as dy”) yn plak fan yn oeren. Se binne net om teams mei inoar te fergelykjen.","also":["story point","ferhaalpunten"]},{"id":"tshirt","g":"plan","word":"T-shirtmaten","text":"De grutte fan wurk riede as S, M, L of XL. Rap en goed genôch foar betide planning.","also":["t-shirtmaten"]},{"id":"poker","g":"plan","word":"Planning poker","text":"In spultsje om te skatten: elkenien lit tagelyk in grutte-kaart sjen, dan lizze de heechste en leechste út wêrom.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Ofhinklikheid","text":"As ien stik wurk net begjinne of einigje kin oant in oar dat docht.","also":["ofhinklikheden"]},{"id":"blocker","g":"plan","word":"Blokkearder","text":"Alles wat it wurk no stopet, lykas in antwurd dat ûntbrekt of in ark dat stikken is.","also":["blokkearders","blocker"]},{"id":"deadline","g":"plan","word":"Deadline","text":"De datum dêr’t wat foar klear wêze moat.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Oplevering","text":"Wat konkreets dat it wurk opleveret en oerdraacht, lykas in wurkjende side of in rapport.","also":["opleveringen","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Foarsizzing","text":"In foarsizzing fan wat wierskynlik bart, lykas wannear’t it wurk klear is, op grûn fan wat do oant no ta witst.","also":["foarsizzings"],"noTip":1},{"id":"metric","g":"plan","word":"Metryk","text":"Alles wat do mjitst en yn de tiid folgest, lykas sidebesites of hoe lang it duorret om in flater te reparearjen.","also":["metryken"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Wat minsken dy fertelle oer dyn wurk, goed en min. It betiid en faak krijen is it hert fan Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"De wachtlist fan ideeën en wurk dat noch net ynplanne is, mei it wichtichste boppe-oan. Dêr wurdt neat oan wurke oant it nei Te dwaan giet."},{"id":"sprint","g":"agile","word":"Sprint","text":"In koarte, fêste perioade fan wurk (faak ien of twa wiken, nea mear as in moanne) mei in doel en in ôfpraat set kaarten om ôf te meitsjen.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"In flugge deistige ynchecking: wat elk teamlid die, wat er dêrnei docht, en wat him ophâldt. Yn Scrum hjit it de deistige scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","steand oerlis"]},{"id":"kanban","g":"agile","word":"Kanban","text":"In wurkwize dêr’t kaarten oer de kolommen fan in boerd hinne gean (lykas Te dwaan, Dwaande, Klear) en it team beheint hoefolle der tagelyk dwaande is, sadat it wurk trochstreamt."},{"id":"wip","g":"agile","word":"WIP-limyt","text":"WIP is koart foar work in progress. In WIP-limyt is it grutste oantal kaarten dat in kolom tagelyk befetsje mei, sadat it team dingen ôfmakket foardat it mear begjint.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"De koarte kontrôlelist fan it team foar wat „klear“ betsjut, lykas test en útlein, foardat in kaart nei dy ta giet. Syn twilling, de Definition of Ready, seit wannear't in kaart dúdlik genôch is om te begjinnen.","also":["Definition of Ready","DoD","DoR","Definition of Done"]},{"id":"retro","g":"agile","word":"Retro","text":"In geregeld weromsjen op hoe't it team wurket, om ôf te sprekken oer ien of twa dingen om de folgjende kear better te dwaan. Koart foar retrospective. Yn AI-gile stelt in retro in feroaring foar yn de wurkwize fan it team, en do seist Go of Noch net.","also":["retro's","retrospektive","retrospektiven"]},{"id":"swarm","g":"agile","word":"Swerm","text":"Alle hannen oan dek: in protte minsken lizze oar wurk del om tegearre ien driuwend ding op te lossen oant it regele is. Yn AI-gile helpt elk team by ien projekt, wylst oare projekten wachtsje.","also":["swarm","swarming","swermje"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Yn Scrum de persoan dy’t it team helpt goed te wurkjen: rêdt út ’e wei wat harren hindert, hâldt gearkomsten op koers en leart harren goede gewoanten, sûnder ien te kommandearjen. Yn AI-gile sjocht de Lead Scrum Master fêstsittende kaarten, stjit de teams oan en herinnert dy oan wat wachtet, oer alle projekten hinne.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"In wize fan wurkjen yn lytse stappen: in bytsje bouwe, faak echte resultaten sjen litte, leare fan wat minsken sizze en ûnderweis it plan feroarje, yn plak fan alles fan tefoaren te plannen.","also":["Agile ûntwikkeling","agile wurkwize"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"In koarte ferklearring, yn 2001 skreaun troch softwaremakkers. It set minsken, wurkjende resultaten, nau gearwurkjen mei klanten en reagearjen op feroaring boppe swiere plannen en papierwurk.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Wetterfal","text":"De âldere wurkwize: alles plannen, dan alles bouwe, dan alles testen, ien faze nei de oare. Feroaringen let yn it proses binne dreech en djoer.","also":["wetterfalmodel","waterfall"]},{"id":"iteration","g":"agile","word":"Iteraasje","text":"Ien rûnte fan wat bouwe, it kontrolearje en ferbetterje. Agile wurk is in keatling dêrfan, en in sprint is ien soart.","also":["iteraasjes"]},{"id":"increment","g":"agile","word":"Ynkrement","text":"In nij wurkjend stik dat yn in sprint of rûnte fan wurk oan it produkt tafoege wurdt en past by wat der al wie.","also":["ynkreminten"]},{"id":"scrum","g":"agile","word":"Scrum","text":"In populêre Agile wurkwize: in lyts team wurket yn koarte sprints nei in doel, mei fêste rollen en in pear geregelde gearkomsten om te plannen, te kontrolearjen en te ferbetterjen."},{"id":"scrumteam","g":"agile","word":"Scrum-team","text":"De lytse groep dy’t it wurk docht yn Scrum: in produkteigener, in Scrum Master en de ûntwikkelders.","also":["Scrum-teams"]},{"id":"ceremonies","g":"agile","word":"Scrum-eveneminten","text":"De geregelde gearkomsten yn Scrum: sprintplanning, de deistige scrum, de sprintevaluaasje en de retro. In protte minsken neame se seremoanjes.","also":["seremoanjes","Scrum-seremoanjes"]},{"id":"sprintplan","g":"agile","word":"Sprintplanning","text":"De gearkomste oan it begjin fan in sprint dêr’t it team it oer iens wurdt wêrom’t de sprint wichtich is, hokker kaarten oppakt wurde en hoe’t se begjinne.","also":["planningsgearkomste"]},{"id":"sprintgoal","g":"agile","word":"Sprintdoel","text":"Ien sin dy’t seit wêr’t in sprint foar is. Lytse taken kinne ûnderweis feroarje, salang’t it doel helle wurdt.","also":["sprintdoelen"]},{"id":"sprintbacklog","g":"agile","word":"Sprintbacklog","text":"De kaarten keazen foar de hjoeddeistige sprint, mei it plan fan it team om se te dwaan.","also":["sprintbacklogs"]},{"id":"productbacklog","g":"agile","word":"Produktbacklog","text":"De folsleine list op folchoarder fan alles wat foar it produkt boud wurde kin, it wichtichste boppe-oan. Hy feroaret hieltyd mei wat do learst.","also":["produktbacklogs"]},{"id":"productgoal","g":"agile","word":"Produktdoel","text":"It gruttere resultaat dêr’t it produkt nei wurket, dat it team helpt kieze wat er dwaan moat.","also":["produktdoelen"]},{"id":"refinement","g":"agile","word":"Backlog-ferfining","text":"It backlog geregeld trochgean om kaarten op te romjen, te splitsen, op folchoarder te setten en mei details oan te foljen, sadat se klear binne om op te pakken. Ek wol backlog grooming neamd.","also":["backlog grooming","refinement","ferfining"]},{"id":"sprintreview","g":"agile","word":"Sprintevaluaasje","text":"In gearkomste oan it ein fan in sprint dêr’t it team toant wat it ôfmakke hat en heart wat minsken derfan fine, om te beslúten wat der folget.","also":["sprintevaluaasjes"]},{"id":"demo","g":"agile","word":"Demo","text":"Klear wurk live yn aksje sjen litte oan de minsken dy’t derom frege hawwe.","also":["demo’s"],"noTip":1},{"id":"timebox","g":"agile","word":"Tiidfak","text":"In fêste hoemannichte tiid foar wat. As it om is, hâldst op, ek al is net alles klear.","also":["tiidfakken","timebox"]},{"id":"velocity","g":"agile","word":"Snelheid","text":"Hoefolle wurk in team meastal ôfmakket yn in sprint, brûkt om te plannen hoefolle der de folgjende kear oppakt wurdt. It is gjin sifer foar hoe hurd minsken wurkje.","also":["teamsnelheid","velocity"]},{"id":"capacity","g":"agile","word":"Kapasiteit","text":"Hoefolle wurk it team oppakke kin yn in perioade, nei fakânsjes en oar wurk.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown-diagram","text":"In diagram fan it wurk dat oer is yn in sprint, dat dei foar dei omleech giet. As de line plat bliuwt, sit der wat fêst.","also":["burndown","burn-down"]},{"id":"burnup","g":"agile","word":"Burnup-diagram","text":"In diagram fan klear wurk dat mei de tiid omheech giet, njonken it totaal plande, sadat do sjen kinst wannear’t do der komst.","also":["burnup","burn-up"]},{"id":"kanbanboard","g":"agile","word":"Kanban-boerd","text":"It boerd sels: in kolom foar eltse faze fan it wurk, mei kaarten dy’t fan kolom nei kolom skowe.","also":["Kanban-boerden"]},{"id":"pullsys","g":"agile","word":"Lûksysteem","text":"In wurkwize dêr’t nij wurk allinnich begjint as immen romte hat om it op te pakken, yn plak fan op in fol bord skood te wurden.","also":["pull-based","lûkbasearre"]},{"id":"flow","g":"agile","word":"Flow","text":"Hoe soepel wurk oer it boerd hinne giet. Goede flow betsjut dat kaarten trochgean yn plak fan har op te stapeljen.","also":["wurkstream","trochstream","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Trochrintiid","text":"Hoe lang it duorret fan dat immen om wat freget oant it klear is.","also":["trochrintiden","lead time"]},{"id":"cycletime","g":"agile","word":"Syklustiid","text":"Hoe lang in kaart nedich hat fan it momint dat it wurk der echt oan begjint oant it klear is.","also":["syklustiden","cycle time"]},{"id":"throughput","g":"agile","word":"Trochfier","text":"Hoefolle kaarten der yn in wike klear komme, of yn in oare fêste tiid.","also":["trochfiersnelheid","throughput"]},{"id":"bottleneck","g":"agile","word":"Knelpunt","text":"De iene faze dêr’t wurk opstapelt en alles dêrefter fertraget, lykas de smelle hals fan in flesse.","also":["knelpunten","bottleneck"]},{"id":"swimlane","g":"agile","word":"Swimbaan","text":"In rige oer it boerd dy’t kaarten fan ien soart groepearret, lykas driuwend wurk of de kaarten fan ien team.","also":["swimbanen","swimlane"]},{"id":"lean","g":"agile","word":"Lean","text":"In wurkwize dy’t ferspilling (alles wat de klant net helpt) fuorthellet en it wurk yn beweging hâldt."},{"id":"waste","g":"agile","word":"Ferspilling","text":"Yn Lean alles wat muoite kostet mar de klant net helpt, lykas wachtsjen, opnij dwaan of dingen bouwe dy’t nimmen brûkt.","noTip":1},{"id":"kaizen","g":"agile","word":"Trochgeande ferbettering","text":"Hieltyd in bytsje better wurde troch lytse geregelde feroaringen, en dan kontrolearje oft se holpen. Retro’s binne ien manier. Ek wol kaizen neamd.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Selsorganisearjend team","text":"In team dat sels beslút hoe’t it wurk dien wurdt, yn plak fan stap foar stap te hearren wat it dwaan moat.","also":["selsorganisearjend","selsstjoerend team"]},{"id":"crossfunc","g":"agile","word":"Multydissiplinêr team","text":"In team dat alle feardigens hat dy’t it nedich hat om it wurk sels ôf te meitsjen, lykas ûntwerp, bouwen en testen.","also":["cross-functional","cross-funksjoneel"]},{"id":"spike","g":"agile","word":"Spike","text":"In koart stik ûndersyk mei in fêste tiidslimyt, om in fraach te beäntwurdzjen foardat do it echte wurk tasizzest.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Wurk opnij dwaan om’t it de earste kear net goed wie.","also":["reworked","oerdwaan","opnij dien"]},{"id":"safe","g":"agile","word":"Agile op skaal (SAFe)","text":"Manieren om Agile oer in protte teams yn in grutte organisaasje te brûken. SAFe (it Scaled Agile Framework) is ien bekend foarbyld.","also":["scaled Agile","agile op skaal"]},{"id":"repo","g":"build","word":"Repo","text":"De map fan it projekt mei koade en syn folsleine skiednis fan commits. Hy kin op dyn kompjûter stean, op GitHub, of beide.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"In aparte line fan wurk yn de koade, sadat wizigingen makke wurde kinne sûnder de haadferzje oan te rekken.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"In bewarre momintopname fan de koade, mei in koart notysje fan wat feroare is. Do kinst altyd werom nei ien.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Dyn bewarre momintopnames (commits) fan dizze kompjûter nei de dielde kopy online stjoere, lykas GitHub, sadat der in reservekopy fan is en oaren se krije kinne."},{"id":"merge","g":"build","word":"Merge","text":"De feroarings fan ien branch yn in oare gearfoegje, meastal werom yn de haadferzje."},{"id":"pr","g":"build","word":"Pull request","text":"Freegje om de feroarings fan in branch te kontrolearjen en yn de haadferzje gearfoegje te litten. Guon siden neame it in merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"De koade opromje sûnder te feroarjen wat er docht: lytsere bestannen, dúdlikere nammen, minder werhelling."},{"id":"bug","g":"build","word":"Bug","text":"Wat net wurket sa't it moat.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"In twadde pear eagen: immen oars as de skriuwer kontrolearret it wurk foardat it by dy komt, sadat minder flaters troch komme. Yn AI-gile kontrolearret in oare AI eltse kaart.","also":["code review","koadereview"]},{"id":"code","g":"build","word":"Koade","text":"De skreaune ynstruksjes dy’t in kompjûter fertelle wat er dwaan moat. Ek wol boarnekoade neamd.","also":["boarnekoade"],"noTip":1},{"id":"proglang","g":"build","word":"Programmeartaal","text":"In taal om koade yn te skriuwen, lykas JavaScript, Python of Java. Elk past by in oar soart wurk.","also":["programmeartalen"]},{"id":"developer","g":"build","word":"Ûntwikkelder (dev)","text":"Immen dy’t koade skriuwt en feroaret. Ek wol programmeur of software engineer neamd.","also":["ûntwikkelder","ûntwikkelders","programmeur","programmeurs","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programma’s dy’t op kompjûters en tillefoans rinne, yn tsjinstelling ta de masines sels (de hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Koart foar applikaasje: in programma dat minsken brûke om wat dien te krijen, op in tillefoan, in kompjûter of yn in webblêder.","also":["apps","applikaasje","applikaasjes"],"noTip":1},{"id":"webapp","g":"build","word":"Web-app","text":"In app dy’t yn in webblêder rint, sadat der neat ynstallearre hoecht te wurden.","also":["web-apps","webapplikaasje"]},{"id":"frontend","g":"build","word":"Front end","text":"It part fan in app dat do sjochst en oanklikest: de skermen, knoppen en wurden, faak yn dyn webblêder.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"It part efter de skermen fan in app dat de gegevens bewarret en it wurk docht as do wat oanklikest, lykas dyn wachtwurd kontrolearje.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Wurkje oan sawol de front end as de back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"Brûkersomjouwing (UI)","text":"Wat in persoan op it skerm sjocht en brûkt: yndieling, knoppen, menu’s en tekst.","also":["UI","user interface","brûkersynterface"]},{"id":"ux","g":"build","word":"Brûkerservaring (UX)","text":"Hoe’t it field om wat te brûken: maklik, dúdlik en noflik, of ferwarrend en stadich.","also":["UX","user experience","brûkerservaring"]},{"id":"accessibility","g":"build","word":"Tagonklikheid (a11y)","text":"Dingen brûkber meitsje foar elkenien, ek foar minsken dy’t min sjen kinne, gjin mûs brûke kinne of in skermlêzer brûke.","also":["a11y","tagonklikheid"]},{"id":"responsive","g":"build","word":"Responsyf ûntwerp","text":"Siden sa meitsje dat se by elke skermgrutte passe en goed wurkje, fan in tillefoan oant in grutte monitor.","also":["responsyf"]},{"id":"designsys","g":"build","word":"Ûntwerpsysteem","text":"In dield pakket fan kleuren, lettertypen, knoppen en regels, sadat elk skerm der itselde útsjocht en itselde wurket.","also":["ûntwerpsystemen","design system"]},{"id":"architecture","g":"build","word":"Arsjitektuer","text":"De algemiene foarm fan in systeem: wat de haadûnderdielen binne en hoe’t se mei inoar prate."},{"id":"database","g":"build","word":"Databank (DB)","text":"In oardere opslach fan ynformaasje, as in tige krêftich rekkenblêd dat de app lêze en feroarje kin.","also":["databank","databanken","database","DB"]},{"id":"schema","g":"build","word":"Databankskema","text":"De yndieling fan in databank: hokker tabellen mei ynformaasje er hat en wat yn eltse komt.","also":["skema","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Koart foar structured query language: de taal dêr’t in protte databanken mei frege wurdt om ynformaasje of om it te feroarjen.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Gegevens","text":"Ynformaasje dy’t in kompjûter bewarret, lykas nammen, bestellingen of ynstellings.","also":["dataset","datasets","data"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"In kompjûter dy’t altyd oan stiet en fersiken fan oare kompjûters beäntwurdet, lykas in webside stjoere as do der hinne giest.","also":["servers","tsjinner"]},{"id":"client","g":"build","word":"Client","text":"De kant dy’t om wat freget, meastal dyn webblêder of app, dy’t mei in server praat. Yn it bedriuwslibben betsjut it ek gewoan in klant.","also":["clients","kliïnt"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Koart foar application programming interface: in fêst menu fan fersiken dy’t ien programma oan in oar dwaan kin, lykas in waarstsjinst freegje om de foarsizzing fan hjoed.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Einpunt","text":"Ien ûnderdiel fan it menu fan in API: in webadres dat in programma oproppe kin om wat op te heljen of te stjoeren.","also":["einpunten","endpoint"]},{"id":"integration","g":"build","word":"Yntegraasje","text":"Twa systemen mei inoar ferbine, sadat se gearwurkje, lykas dyn winkel dy’t bestellingen nei dyn boekhâldingsprogramma stjoert.","also":["yntegraasjes","integration"]},{"id":"webhook","g":"build","word":"Webhook","text":"In berjocht dat ien systeem fan himsels nei in oar stjoert sadree’t der wat bart, lykas “betelling ûntfongen”.","also":["webhooks"]},{"id":"library","g":"build","word":"Bibleteek","text":"Klearmakke koade dy’t in oar skreaun hat en dy’t do opnij brûke kinst yn stee fan it sels te skriuwen.","also":["bibleteken","library"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"In klearmakke struktuer foar it bouwen fan in app dy’t foar in grut part bepaalt hoe’t de koade opset is, as it ramt fan in hûs dat do ynfolst.","also":["frameworks","ramt"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"In doaze mei ark, koade en foarbylden om software te bouwen foar ien platfoarm of tsjinst.","also":["SDK","SDK’s"]},{"id":"softdep","g":"build","word":"Software-ofhinklikheid","text":"In bibleteek of ark dat dyn koade nedich hat om te wurkjen. Se bywurke hâlde is wichtich foar de feiligens.","also":["software-ofhinklikheden","software dependencies"]},{"id":"package","g":"build","word":"Pakket","text":"In bondel klearmakke koade dy’t do ynstallearje en brûke kinst yn in projekt.","also":["pakketten","package"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pakketbehearder","text":"In ark dat de pakketten opheelt en bywurket dêr’t dyn koade fan ôfhinklik is. npm is in bekende.","also":["pakketbehearders","package manager","npm"]},{"id":"git","g":"build","word":"Git","text":"It meast brûkte ark om de skiednis fan koadeferoarings te bewarjen, as commits en branches."},{"id":"github","g":"build","word":"GitHub","text":"In webside dy’t Git-repo’s online hâldt, sadat teams koade diele, feroarings beoardiele en wurk folgje kinne."},{"id":"vcs","g":"build","word":"Ferzjebehear","text":"In folsleine skiednis hâlde fan elke feroaring oan de bestannen, sadat do sjen kinst wa’t wat feroare hat en werom kinst as it nedich is. Git docht dit.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Kloane","text":"Dyn eigen folsleine kopy meitsje fan in repo, mei de skiednis, op dyn kompjûter.","also":["kloand","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"De nijste commits fan de dielde kopy (lykas GitHub) op dyn kompjûter helje. It tsjinoerstelde fan push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Haadtûke","text":"De offisjele ferzje fan de koade dêr’t elkenien fan útgiet, faak main of master neamd.","also":["master branch","main branch"]},{"id":"conflict","g":"build","word":"Gearfoegingskonflikt","text":"As twa feroarings deselde rigels op ferskillende wize rekke, sadat de kompjûter se net gearfoegje kin en in persoan kieze moat.","also":["merge conflicts","merge conflict"]},{"id":"diff","g":"build","word":"Diff","text":"In werjefte dy’t krekt sjen lit wat feroare is tusken twa ferzjes: tafoege rigels en fuorthelle rigels.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Dyn eigen kopy fan immen oars syn repo, dy’t do feroarje kinst sûnder syn repo te beynfloedzjen.","also":["forks","forked"]},{"id":"script","g":"build","word":"Skript","text":"In koart programma dat sels ien klus docht, lykas bestannen opromje of de app starte.","also":["skripts","script"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"De koade omsette yn wat klear is om te rinnen, of it klearmakke resultaat sels.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompilearje","text":"Koade dy’t minsken skreaun hawwe omsette yn in foarm dy’t de kompjûter direkt útfiere kin.","also":["kompilearre","compiler"]},{"id":"cli","g":"build","word":"Kommandorigel (CLI)","text":"In tekstfinster dêr’t do ynstruksjes foar de kompjûter yntypst yn stee fan te klikken. Ek wol terminal neamd.","also":["command line","command-line","CLI","terminal","kommandorigel"]},{"id":"config","g":"build","word":"Konfiguraasje (config)","text":"De ynstellings dy’t bepale hoe’t software him gedraacht, apart fan de koade hâlden, sadat se maklik te feroarjen binne.","also":["config","configuration","konfiguraasje"],"noTip":1},{"id":"envvar","g":"build","word":"Omjouwingsfariabele","text":"In ynstelling dy’t oan in programma meijûn wurdt as it start, faak brûkt foar adressen of wachtwurden, sadat se net yn de koade skreaun wurde.","also":["omjouwingsfariabelen","environment variable","env var"]},{"id":"debugging","g":"build","word":"Debuggen","text":"Opspoare wêrom’t wat net wurket, en it reparearje.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Twa minsken (of in persoan en in AI) dy’t tegearre oan deselde koade wurkje: de iene typt en de oare kontrolearret.","also":["pairing","pearprogrammearjen"]},{"id":"docs","g":"build","word":"Dokumintaasje (docs)","text":"Skreaune útlis fan hoe’t wat wurket of hoe’t it brûkt wurdt.","also":["documentation","docs","dokumintaasje"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"It earste bestân om te lêzen yn in repo: wat it projekt is en hoe’t do it oan ’e gong krijst.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy-systeem","text":"In âlder systeem dat noch yn gebrûk is en dreech te feroarjen, faak om’t mar in pear minsken it noch begripe.","also":["legacy systems","legacy code","âld systeem"]},{"id":"techdebt","g":"build","word":"Technyske skuld","text":"Koarte bochten dy’t no tiid besparje, mar lettere feroarings stadiger meitsje, as in liening dêr’t hieltyd mear rinte op komt. Refactoring (de koade opromje) lost it ôf.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"In kontrôle dat wat wurket sa’t it moat. Guon tests rint de kompjûter sels eltse kear as de koade feroaret; oaren binne dat do in kaart dy’t klear is útprobearrest foardat do him akseptearrest.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Koart foar quality assurance: alles wat dien wurdt om wis te wêzen dat wurk goed is foardat it live giet. Yn AI-gile betsjut dat de automatyske kontrôles: as QA read is, is wat mislearre, en it kin net live oant dat reparearre is.","also":["kwaliteitskontrôle","kwaliteitskontrôles","kwaliteitsfersekering"]},{"id":"testpile","g":"test","word":"Teststapel","text":"De kleare kaarten dy't wachtsje oant do se útprobearrest, de iene nei de oare. Akseptearje der ien of stjoer him werom mei in notysje, en de folgjende komt.","also":["teststapels"]},{"id":"autotest","g":"test","word":"Automatearre test","text":"In kontrôle dy’t de kompjûter sels útfiert eltse kear as de koade feroaret, om flaters betiid te finen.","also":["automated tests","automatic tests","automatearre tests"]},{"id":"manualtest","g":"test","word":"Hânmjittige test","text":"In persoan dy’t it wurk mei de hân besiket om te sjen oft it docht wat it moat.","also":["manual tests","manual testing","hânmjittige tests"]},{"id":"unittest","g":"test","word":"Ienheidstest","text":"In lytse automatyske kontrôle fan ien lyts stikje koade op himsels.","also":["unit tests","ienheidstests"]},{"id":"integtest","g":"test","word":"Yntegraasjetest","text":"In kontrôle dat ferskate dielen goed gearwurkje, net allinnich elk apart.","also":["integration tests","integration test"]},{"id":"endtoend","g":"test","word":"Ein-oant-ein-test (E2E)","text":"In test dy’t docht as in echte brûker fan begjin oant ein, lykas oanmelde, keapje en betelje.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Brûkersakseptaasjetest (UAT)","text":"De minsken dy’t om it wurk frege hawwe probearje it sels en sizze oft it docht wat se nedich hawwe. De testhoop fan AI-gile is har ferzje dêrfan.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regresje","text":"Wat eartiids wurke, mar nei in feroaring stikken gie. Regresjetests kontrolearje dat de âlde dingen noch wurkje.","also":["regressions","regression test","regression tests","regression testing","regresjetest"]},{"id":"smoke","g":"test","word":"Smoketest","text":"In hiel rappe kontrôle oft de haaddingen oerhaupt wurkje, bygelyks krekt nei’t in feroaring live giet. As it mislearret, hâld dan op en sjoch wat der is.","also":["smoke tests","smoke test"]},{"id":"exploratory","g":"test","word":"Ferkennende test","text":"It produkt frij útprobearje en der op ferskillende manieren yn porje, om problemen te finen dy’t plande kontrôles misse soene.","also":["exploratory test","exploratory tests","exploratory testing"]},{"id":"testcase","g":"test","word":"Testgefal","text":"Ien skreaun senario om út te probearjen: de stappen, en wat der barre moat.","also":["test cases","test case","testgefallen"]},{"id":"coverage","g":"test","word":"Testdekking","text":"Hoefolle fan de koade troch automatyske tests kontrolearre wurdt. Mear is meastal feiliger, mar hege dekking allinnich bewiist net dat it goed wurket.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Testgegevens","text":"Ferbeelde foarbyldynformaasje dy’t by it testen brûkt wurdt, sadat gjin priveegegevens fan echte minsken bleatsteld wurde.","also":["test fixtures","test data"]},{"id":"edgecase","g":"test","word":"Grinsgefal","text":"In ûngewoane situaasje oan de rânen, lykas in leech formulier of in namme mei in apostrof, dêr’t dingen faak stikken gean.","also":["edge cases","edge case"]},{"id":"happypath","g":"test","word":"Lokkich paad","text":"De gewoane rûte dêr’t alles goed giet. Goed testen besiket ek de ûnlokkige paden."},{"id":"perftest","g":"test","word":"Prestaasjetest","text":"Kontrolearje hoe fluch wat is en hoe goed it tsjin druk kin.","also":["performance test","performance tests","performance testing"]},{"id":"loadtest","g":"test","word":"Belestingstest","text":"Kontrolearje hoe in systeem it docht as in protte minsken it tagelyk brûke.","also":["load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Feiligenstest","text":"Sykje nei swakke plakken dêr’t immen in systeem mei misbrûke koe of sjen koe wat er net sjen mei.","also":["security test","security tests","security testing"]},{"id":"accesstest","g":"test","word":"Tagonklikheidstest","text":"Kontrolearje dat minsken mei ferskillende mooglikheden it produkt brûke kinne, ek mei in skermlêzer of allinnich in toetseboerd.","also":["accessibility test","accessibility testing"]},{"id":"linting","g":"test","word":"Linting","text":"In automatyske kontrôle dy’t wierskynlike flaters en rommelige styl yn koade fynt, as in staveringskontrôle foar programma’s.","also":["linter","lint"]},{"id":"static","g":"test","word":"Statyske analyze","text":"Koade kontrolearje op problemen troch it automatysk te lêzen, sûnder it út te fieren.","also":["static code analysis","static analysis"]},{"id":"flaky","g":"test","word":"Ûnbetroubere test","text":"In test dy’t soms slagget en soms mislearret sûnder dat der in dúdlike reden is, sadat er net folslein fertroud wurde kin.","also":["flaky tests","flaky test"]},{"id":"repro","g":"test","word":"Reprodusearje (repro)","text":"In bug opsetlik wer litte barre troch deselde stappen te folgjen, sadat er bestudearre en reparearre wurde kin. Dy stappen opskriuwe is it nuttichste part fan in bugmelding.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Earnst","text":"Hoe slim it effekt fan in probleem is, fan in lytse ergernis oant alles dat stilstiet.","also":["severity level","severity"]},{"id":"deploy","g":"change","word":"Deploy","text":"In nije ferzje fan de software op de kompjûters sette dêr’t it op rint, lykas in testkopy of de live-tsjinst."},{"id":"release","g":"change","word":"Release","text":"In beneamde bondel klear wurk dat tegearre live giet, mei koarte notysjes oer wat der feroare is. 🚀 Releases skriuwt de notysjes út de kleare kaarten.","also":["releases","ferzje","ferzjes"]},{"id":"rollback","g":"change","word":"Rollback","text":"Weromgean nei de lêste ferzje dy’t wurke as in nije problemen jout. Yn AI-gile sammelet Roll back de weromdraaistappen dy’t by eltse feroaring skreaun binne yn ien kontrôlelist.","also":["weromdraaie","weromdraaid","rollbacks"]},{"id":"live","g":"change","word":"Live","text":"De echte ferzje dy't minsken brûke, yn tsjinstelling ta in kopy om dingen út te probearjen. Untwikkelers neame it ek produksje.","also":["produksje","production"],"noTip":1},{"id":"change","g":"change","word":"Wiziging","text":"In plande wiziging oan iets dêr't minsken op rekkenje, earst opskreaun: wat, wêrom, it risiko, wannear en hoe't it weromdraaid wurdt. Begjin der ien mei 🔀 Wiziging oanfreegje.","also":["wizigingen","wizigingsfersyk","wizigingsfersiken"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Iets dat mis gean kin, mei in skoare foar hoe wierskynlik en hoe slim it wêze soe. ⚠️ Risiko's hâldt se yn ien list, heechste skoare foarop, elk mei in datum om der nochris nei te sjen.","also":["risiko's","risikolist","risikoregister"]},{"id":"chgwin","g":"change","word":"Wizigingsfinster","text":"De tiden dat wizigingen live gean meie, lykas in stille tiisdeitejûn. Bûten in finster kin in wizigingskaart net ôfmakke wurde, útsein by in need.","also":["wizigingsfinsters"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"In lêste kontrôle krekt foardat in feroaring live giet: elke persoan dy’t goedkarre moat seit Go of No go. It giet allinnich troch as elkenien Go seit.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Goedkarring","text":"Wachtsje op in ja foardat it wurk begjint. In kaart dy't in freon oanmakket, of in wiziging, wachtet yn ✅ Goedkarrings oant do him goedkarst of ôfwiist.","also":["goedkarrings","goedkarren"]},{"id":"quiettime","g":"change","word":"Stille tiid","text":"In perioade, lykas by in livestream, in demo of nachts, wêryn neat live giet. De teams wurkje en teste troch, mar live gean wachtet oant it foarby is. Op oare plakken hjit it in change freeze.","also":["stille tiden","change freeze","wizigingsstop"]},{"id":"devops","g":"change","word":"DevOps","text":"In wurkwize dêr’t de minsken dy’t software bouwe en de minsken dy’t it draaiende hâlde as ien team wurkje, mei in protte automatisearring, sadat feroarings faak en feilich live gean."},{"id":"cicd","g":"change","word":"CI/CD (trochgeande yntegraasje en levering)","text":"Elkenien syn feroarings wurde faak yn de haadferzje gearfoege en eltse kear automatysk kontrolearre (trochgeande yntegraasje), sadat de software altyd klear is om mei in knopdruk live te gean (trochgeande levering).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Trochgeande útrol","text":"Ien stap fierder as trochgeande levering: elke feroaring dy’t de kontrôles trochkomt giet sels live, sûnder knop om op te drukken.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"De automatyske rige stappen dêr’t in feroaring troch giet op wei nei live, lykas bouwe, testen en dan útrolje.","also":["pipelines"]},{"id":"environment","g":"change","word":"Omjouwing","text":"Ien aparte kopy fan it systeem foar ien doel, lykas ien om yn te bouwen, ien om yn te testen en de live-ferzje.","also":["omjouwings","environment"],"noTip":1},{"id":"devenv","g":"change","word":"Ûntwikkelomjouwing","text":"De kopy dêr’t in ûntwikkelder yn wurket, faak op syn eigen kompjûter, dêr’t dingen stikmeitsje nimmen skea docht.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Testomjouwing","text":"In aparte kopy fan it systeem allinnich foar testen, sadat de echte tsjinst net oanrekke wurdt.","also":["test environments","test environment"]},{"id":"staging","g":"change","word":"Staging","text":"In lêste kopy ynsteld krekt as live, foar in einkontrôle foardat in feroaring live giet.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build-artefakt","text":"It bestân of de bondel dy’t in build opleveret, klear om bewarre, kontrolearre of live set te wurden.","also":["build artifacts","build artifact"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"In driuwende reparaasje dy’t flot live set wurdt, bûten it gewoane plan, om’t wat wichtichs stikken is.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"In lytse fernijing dy’t in bug reparearret of in feiligensgat slút. Feiligenspatches flot tapasse is wichtich.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Ferzjenûmer","text":"In label as 2.4.1 dat seit hokker útjefte do hast. Faak feroaret it earste getal by grutte feroarings en it lêste by lytse reparaasjes.","also":["ferzjenûmers","semantic versioning","version numbers"]},{"id":"relnotes","g":"change","word":"Útjeftenotysjes","text":"In koarte gewoane list fan wat der feroare is yn in útjefte, foar de minsken dy’t it brûke, mei reparaasjes en bekende grinzen. Ek wol changelog neamd.","also":["changelog","change log","release notes"]},{"id":"flag","g":"change","word":"Funksjeskeakelder","text":"In oan-en-út-skeakelder foar in funksje, sadat nij wurk ferburgen live gean kin en oan (of wer út) set wurde kin sûnder nije útjefte.","also":["feature flags","feature toggle","feature toggles","feature flag"]},{"id":"rollfwd","g":"change","word":"Foarút reparearje","text":"In minne útjefte reparearje troch flot in nije, korrizjearre ferzje út te bringen yn stee fan werom te gean nei de âlde.","also":["rolling forward","rolled forward","roll forward"]},{"id":"canary","g":"change","word":"Kanaryútjefte","text":"In feroaring earst foar in lytse groep live sette, en pas foar elkenien as it goed liket. Neamd nei de kanaryfûgels dy’t mynwurkers ûnder de grûn meinamen as betide warskôging.","also":["canary releases","canary","canary release"]},{"id":"bluegreen","g":"change","word":"Blau-griene útrol","text":"Twa kopyen fan it live-systeem hâlde en minsken yn ien kear nei de nije oerskeakelje, sadat do daliks werom kinst as it mis giet.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Útrol sûnder stilstân","text":"In nije ferzje live sette sûnder dat de tsjinst foar syn brûkers ea stopt.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Feroaringsbehear","text":"Feroarings helpe slagje: it risiko beoardiele, de goeie goedkarring krije en in goed momint kieze. Ek wol change management neamd.","also":["change management","change enablement"]},{"id":"cab","g":"change","word":"Feroaringsadviesried (CAB)","text":"In groep dy’t wichtige feroarings besjocht en ôfsprekt oft en wannear’t se trochgean meie.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standertferoaring","text":"In feroaring mei leech risiko dy’t eltse kear op deselde beproefde wize dien wurdt, sadat se foarôf goedkard is.","also":["standard changes","standard change"]},{"id":"normchange","g":"change","word":"Gewoane feroaring","text":"In feroaring dy’t kontrolearre en goedkard wurde moat foardat se trochgiet.","also":["normal changes","normal change"]},{"id":"emergchange","g":"change","word":"Needferoaring","text":"In feroaring dy’t daliks barre moat om serieuze problemen te reparearjen of te foarkommen, mei in rappere goedkarring dêrby.","also":["emergency changes","emergency change"]},{"id":"automation","g":"change","word":"Automatisearring","text":"De kompjûter in werhelle klus sels litte dwaan, sadat it flugger giet en eltse kear op deselde wize dien wurdt.","also":["automated","automation"],"noTip":1},{"id":"infra","g":"change","word":"Ynfrastruktuer","text":"De masines, netwerken en tsjinsten dêr’t software op rint.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Ynfrastruktuer as koade (IaC)","text":"Dyn tsjinners en ynstellings beskriuwe yn bestannen dy’t by de koade bewarre wurde, sadat se eltse kear krekt itselde opnij opboud wurde kinne.","also":["IaC"]},{"id":"cloud","g":"change","word":"Wolk","text":"Kompjûters, opslach en tsjinsten hiere fan in grutte oanbieder fia it ynternet, yn stee fan de masines sels te hawwen.","also":["de wolk","cloud","cloud computing"]},{"id":"provider","g":"change","word":"Wolkoanbieder","text":"In bedriuw dat rekkenkrêft ferhierre fia it ynternet, lykas Amazon Web Services (AWS), Microsoft Azure of Google Cloud.","also":["cloud provider","cloud providers","wolkoanbieders"]},{"id":"hosting","g":"change","word":"Hosting","text":"Wêr’t dyn app of webside wennet en rint, sadat minsken der by kinne, meastal hierd fan in bedriuw.","also":["húsfesting"]},{"id":"domain","g":"change","word":"Domeinnamme","text":"It webadres dat minsken yntype, lykas example.com. Do hierst it per jier, dus it moat fernijd wurde.","also":["domain names","domain","domein"]},{"id":"dns","g":"change","word":"DNS","text":"Koart foar domain name system: it adresboek fan it ynternet, dat in namme as example.com omsette yn it adres fan de goeie kompjûter.","also":["domain name system"]},{"id":"container","g":"change","word":"Kontener","text":"In ôfsletten pakket mei in app en alles wat dy nedich hat, sadat it op elke kompjûter itselde rint. Docker is it bekendste ark.","also":["container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Firtuele masine (VM)","text":"In skynkompjûter dy’t binnen in echte rint, sadat ien grutte masine as in protte dwaan kin.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Koade útfiere sûnder sels tsjinners te beheren: de oanbieder lit it rinne as it nedich is en do betellest foar wat do brûkst."},{"id":"lb","g":"change","word":"Load balancer","text":"Wat besikers oer ferskate tsjinners ferdielt, sadat net ien fan harren oerbelêste wurdt.","also":["load balancers","lêstferdieler"]},{"id":"cache","g":"change","word":"Cache","text":"In handige opslach fan resinte resultaten dy’t tichtby hâlden wurdt, sadat itselde net wer opheald of útrekkene hoecht te wurden. It leegmeitsjen kin siden reparearje dy’t ferâldere lykje.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"In wrâldwiid stel tsjinners mei kopyen fan dyn siden en plaatsjes tichtby dyn besikers, sadat se fluch lade.","also":["CDN"]},{"id":"migration","g":"change","word":"Migraasje","text":"Gegevens of systemen ferpleatse fan in âlde opset nei in nije, of foarsichtich feroarje hoe’t in databank opset is.","also":["migrations","database migration","migration"]},{"id":"service","g":"run","word":"Tsjinst","text":"Iets datsto boud hast dêr't minsken op rekkenje, lykas in website of in app, dat ûnderhâlden wurdt sadat it bliuwt wurkjen. Finkje „Dit projekt is in tsjinst“ oan en sis wat er biedt, wa't him brûkt en wa't on-call is.","also":["tsjinsten","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Hoefolle fan de tiid in tsjinst wurket, meastal as persintaazje. 99,9% lit noch altyd likernôch 43 minuten stilstân per moanne ta.","also":["uptime percentage","beskikberenstiid"]},{"id":"uptime","g":"run","word":"Beskikberenskontrôle","text":"In automatyske kontrôle, om de pear minuten, oft dyn tsjinst noch antwurdet. As dy ferskate kearen efterinoar mislearret, iepenet AI-gile sels in incidintkaart.","also":["uptime checks","beskikberenskontrôles"]},{"id":"statuspage","g":"run","word":"Statusside","text":"In iepenbiere side dy't sjen lit oft in tsjinst wurket (grien, oranje of read), mei it lêste nijs, sadat de brûkers sels sjen kinne ynstee fan te freegjen.","also":["statussiden","status page"]},{"id":"desk","g":"run","word":"Servicebalie","text":"It plak dêr't fragen en meldingen fan de minsken dy't dyn tsjinst brûke binnenkomme. AI-gile sortearret elk as fersyk, incidint of idee, en seit it as it liket op wat dat al earder meld is.","also":["servicebalies","balie","service desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Servicefersyk","text":"Immen dy't om wat gewoans freget, lykas in nij akkount of in bytsje help, yn stee fan te melden dat der wat stikken is. It wachtet op syn bar; in incidint giet foar.","also":["servicefersiken"]},{"id":"incident","g":"run","word":"Incidint","text":"Wat stikken is of net goed wurket foar de minsken dy’t it no brûke, lykas dat de webside del is of tige stadich. In 🔥 ynsidintkaart giet foar alles: it wer oan ’e gong krijen komt earst.","also":["incidinten","incident","steuring"]},{"id":"major","g":"run","word":"Major incident","text":"In grut incidint: in soad minsken rekke, of jild of gegevens yn gefaar. Ien knop set alle teams derop (swerm), makket wa't on-call is wekker en freget elke 30 minuten om in statusupdate.","also":["grut incidint","grutte incidinten","major incidents"]},{"id":"oncall","g":"run","word":"On-call","text":"Dejinge wêze dy't reagearret as der wat stikken giet, ek nachts. Elke tsjinst hat in on-call teamlid dat by syn incidinten as earste wekker makke wurdt.","also":["on call","wacht","wachttsjinst"]},{"id":"replyby","g":"run","word":"Reaksjetiid","text":"Hoe lang in kaart op in earste antwurd wachtsje mei, bygelyks in oere foar in incidint. Dêrnei krijt er in reade klok, sadat neat stil fergetten wurdt. Hjit ek wol reaksjedoel.","also":["reaksjetiden","antwurdtermyn","reaksjedoel"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"In koarte weromblik nei in incidint: wat der barde, wat holp en wat der feroarje moat, sûnder ien de skuld te jaan. In incidint kin net sletten wurde sûnder ien.","also":["post-mortems","postmortem","neibeskôging"]},{"id":"problem","g":"run","word":"Probleem","text":"De ferburgen oarsaak efter ien of mear incidinten. In 🧩 probleemkaart bondelet incidinten dy't hieltyd weromkomme, sadat de oarsaak fûn en foar goed reparearre wurdt.","also":["problemen"],"noTip":1},{"id":"rootcause","g":"run","word":"Grûnoarsaak","text":"De echte reden dat der wat stikken gie, net allinnich watsto mis gean seachst. Reparearje de grûnoarsaak en it incidint komt net mear werom.","also":["grûnoarsaken","haadoarsaak","root cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"In manier om dingen draaiende te hâlden oant de echte reparaasje klear is, lykas wat opnij starte as it fêstrint. It stiet op de probleemkaart, sadat net elkenien it opnij útfine moat.","also":["workarounds","needoplossing","tydlike oplossing"]},{"id":"knownerror","g":"run","word":"Bekende fout","text":"In probleem wêrfan de oarsaak begrepen wurdt mar noch net reparearre is, meastal mei in omwei opskreaun. 🧩 Bekende flaters listet se, sadat elkenien de omwei brûkt yn stee fan wer te graven.","also":["bekende fouten","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Stap-foar-stap-ynstruksjes om in bekend soarte swierrichheid op te lossen, sadat it elke kear op deselde manier en fluch dien wurdt. Nei in grut incidint kin it team der ien foarstelle dêrsto OK op seist.","also":["runbooks","draaiboek"]},{"id":"ci","g":"run","word":"Konfiguraasje-item","text":"Ien ding dêr't dyn tsjinst fan ôfhinget, lykas in server, in domein, in sertifikaat, in kaai of in leveransier. 🗂️ Konfiguraasje-items set se per tsjinst op in rige, sadat do sjochst wat in incidint rekket en wat fernijd of back-upt wurde moat.","also":["konfiguraasje-items","configuration item","CI"]},{"id":"expiry","g":"run","word":"Ferrindatum","text":"De datum dat wat ophâldt te wurkjen, útsein as it fernijd wurdt, lykas it feiligenssertifikaat fan in webside of syn webadres. AI-gile hâldt dy datums yn de gaten en makket foar elk 30 dagen fan tefoaren ien kaart om it te fernijen, sadat neat ûnferwachts ophâldt.","also":["ferrindatums","ferrinnen","ferrintoesjoch"]},{"id":"backup","g":"run","word":"Reservekopy","text":"In bewarre kopy fan dyn gegevens fan earder, om op werom te fallen as der wat kwyt rekket of skansearre wurdt. AI-gile makket alle dagen in reservekopy fan dyn boerden.","also":["reservekopyen","backup","back-up"]},{"id":"restore","g":"run","word":"Weromsette","text":"Gegevens weromhelje út in reservekopy. In reservekopy telt pas echt as do witst dat er weromset wurde kin, dus it is de muoite wurdich om dat sa no en dan te probearjen.","also":["weromset","weromsetting","restore"]},{"id":"svcreview","g":"run","word":"Tsjinstreview","text":"In weromblik op ien moanne fan in tsjinst: incidinten iepene en reparearre, hoe fluch minsken in antwurd krigen, beskikberens en brûkte tokens. De Moanlikse review lit it foar elke tsjinst sjen.","also":["tsjinstreviews","moanlikse review","moanlikse reviews"]},{"id":"accessreview","g":"run","word":"Tagongskontrôle","text":"Elke 90 dagen kontrolearje wa’t der noch yn kin: dielde keppelings, rollen fan freonen en bewarre wachtwurden en kaaien. Do hâldst of ferwiderest elk, sadat âlde tagong net bliuwt hingjen.","also":["tagongskontrôles","access review"]},{"id":"improvements","g":"run","word":"Ferbetterlist","text":"Alles wêr't it team better yn wurde wol, op ien plak: retrofoarstellen, reviewaksjes en probleemreparaasjes, elk mei syn status. Do fynst it ûnder 📈 Ferbetteringen.","also":["ferbetterlisten","ferbetteringen"]},{"id":"tokencap","g":"run","word":"Tokenlimyt","text":"In moanlikse limyt op de tokens dy't de aginten fan in tsjinst brûke meie. By 80% krijst in warskôging; by 100% wachtet harren eftergrûnwurk oant de folgjende moanne of oant do de limyt ferheechst.","also":["tokenlimiten","moanlikse tokenlimyt","token cap"]},{"id":"svcmgmt","g":"run","word":"Tsjinstbehear","text":"Alles wat nedich is om in tsjinst nuttich en oan ’e gong te hâlden foar de minsken dy’t derop fertrouwe, dei nei dei."},{"id":"itil","g":"run","word":"ITIL","text":"In breed brûkte hantlieding foar goed tsjinstbehear, mei ûnderwerpen as ynsidinten, problemen en feroarings. De namme stie eartiids foar IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT-tsjinstbehear (ITSM)","text":"Technyk as in tsjinst foar minsken leverje, mei dúdlike wegen om fersiken, ynsidinten, feroarings en ferbetterings oan te pakken.","also":["ITSM"]},{"id":"managed","g":"run","word":"Behearde tsjinst","text":"In tsjinst dy’t in oar foar dy rint en ûnderhâldt, ûnder in oerienkomst oer hoe goed er wurkje moat.","also":["managed services","managed service"]},{"id":"svcowner","g":"run","word":"Tsjinsteigener","text":"De persoan dy’t ferantwurdlik is foar in tsjinst as gehiel: hoe goed er wurket, wat er kostet en hoe’t er better wurdt.","also":["service owners","service owner"]},{"id":"sla","g":"run","word":"Tsjinstnivo-oerienkomst (SLA)","text":"In skriftlike belofte oan klanten oer hoe goed in tsjinst wurkje sil, lykas “99,9% fan de tiid beskikber” of “binnen in oere beäntwurde”, faak mei jild werom as it misgiet.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Tsjinstnivodoel (SLO)","text":"It eigen doel fan it team foar hoe goed in tsjinst wurkje moat oer in perioade, meastal in bytsje strikter steld as de SLA om feilich te wêzen.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Tsjinstnivo-yndikator (SLI)","text":"De werklike mjitting dy’t do tsjin in doel kontrolearrest, lykas it part fan de besites dat goed laden is.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Beskikberens","text":"Oft minsken in tsjinst brûke kinne as se it nedich hawwe, faak mjitten as uptime.","also":["high availability","availability"]},{"id":"downtime","g":"run","word":"Stilstân","text":"Tiid dat in tsjinst net wurket of útskeakele is, pland of net.","also":["down time","downtime"]},{"id":"errorbudget","g":"run","word":"Flaterbudzjet","text":"De lytse hoemannichte mislearring dy’t dyn betrouberensdoel talit. Salang’t der wat oer is, kinst do risiko’s nimme mei feroarings; as it op is, giest do stadiger.","also":["error budgets","error budget"]},{"id":"outage","g":"run","word":"Steuring","text":"In perioade dat in tsjinst foar syn brûkers del is of slim stikken is.","also":["outages","outage"]},{"id":"degraded","g":"run","word":"Fermindere tsjinst","text":"It wurket, mar min: stadich, of mei guon dielen dy’t net wurkje.","also":["degraded service","degraded"]},{"id":"monitoring","g":"run","word":"Tafersjoch","text":"In tsjinst de hiele tiid automatysk yn de gaten hâlde, sadat problemen opmurken wurde, leafst foardat brûkers it fernimme.","also":["monitoring"]},{"id":"observability","g":"run","word":"Observabiliteit","text":"Hoe goed do fan bûten sjen kinst wat der yn in systeem bart, mei help fan de logs, getallen en spoaren.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Log","text":"In trochrinnend deiboek dat in programma hâldt fan wat it docht, brûkt om út te finen wat der mis gie.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Spoar","text":"In ferslach fan hoe’t ien fersyk stap foar stap troch de ferskillende dielen fan in systeem reizget, dat sjen lit wêr’t it fertrage waard.","also":["traces","tracing","trace"]},{"id":"latency","g":"run","word":"Fertraging","text":"Hoe lang it duorret om te antwurdzjen, lykas it wachtsjen tusken klikke en it ferskinen fan de side.","also":["latency","latinsje"]},{"id":"alert","g":"run","word":"Warskôging","text":"In automatysk berjocht dat wat omtinken nedich hat, lykas dat de webside net antwurdet.","also":["alerts","alerting","alert"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Warskôgingswurgens","text":"As der safolle warskôgings binne dat minsken se negearje begjinne, ek de wichtige.","also":["alarm fatigue","alert fatigue","alarmwurgens"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"In skerm dat de wichtichste getallen en statussen yn ien eachopslach sjen lit.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Oproppe","text":"Dringend de persoan dy’t ropdienst hat belje of wekker meitsje oer in probleem.","also":["paged","paging"]},{"id":"escalation","g":"run","word":"Eskalaasje","text":"Immen mei mear feardigens of gesach derby helje as in kwestje net op it hjoeddeiske nivo oplost wurde kin, of net fluch genôch.","also":["escalate","escalated","escalation"]},{"id":"triage","g":"run","word":"Triage","text":"Ynkommende kwestjes flot sortearje op hoe driuwend en wichtich se binne, sadat it slimste earst oanpakt wurdt.","also":["triaged"]},{"id":"impact","g":"run","word":"Ynfloed","text":"Hoefolle wat minsken rekket: hoefolle en hoe slim.","noTip":1},{"id":"urgency","g":"run","word":"Driuwendheid","text":"Hoe gau wat oanpakt wurde moat. Ynfloed en driuwendheid tegearre bepale de prioriteit.","noTip":1},{"id":"plevels","g":"run","word":"Prioriteitsnivo’s (P1, P2…)","text":"Labels foar hoe driuwend in kwestje is. P1 is it slimste en freget daliks aksje.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticketwachtrige","text":"De list fan fersiken en ynsidinten dy’t wachtsje om oppakt te wurden.","also":["ticket queues","ticket queue"]},{"id":"tiers","g":"run","word":"Earste en twadde line","text":"Nivo’s fan stipe: de earste line nimt de oprop oan en lost ienfâldige dingen op; de twadde line hat djippere kennis foar dregere saken. Ek wol tier 1 en tier 2 neamd.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Ynsidintlieder","text":"De iene persoan dy’t de reaksje op in ynsidint liedt, sadat elkenien wit wa’t beslút en wa’t wat docht.","also":["incident commanders","incident commander"]},{"id":"responsetime","g":"run","word":"Reaksjetiid","text":"Hoe lang it duorret foardat immen in fersyk of ynsidint foar it earst oppakt.","also":["response times","response time"]},{"id":"resolution","g":"run","word":"Oplossingstiid","text":"Hoe lang it duorret om in fersyk of ynsidint folslein ôf te hanneljen, fan melding oant reparearre.","also":["resolution times","time to resolve","resolution time"]},{"id":"mttr","g":"run","word":"Gemiddelde hersteltiid (MTTR)","text":"Gemiddeld hoe lang it duorret om in tsjinst wer oan ’e gong te krijen nei’t er stikken gien is. MTTR kin krekt wat ferskillende dingen betsjutte, dus sis wat do mjitst.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Gemiddelde tiid tusken útfal (MTBF)","text":"Gemiddeld hoe lang in tsjinst rint foardat wat stikken giet.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Konfiguraasjedatabank (CMDB)","text":"De list fan al dyn konfiguraasje-items en hoe’t se ferbûn binne, sadat do sjochst wat fan wat ôfhinklik is.","also":["CMDB"]},{"id":"asset","g":"run","word":"Aktivum","text":"Alles fan wearde dat do hast of foar betellest om de tsjinst draaiende te hâlden, lykas in laptop, in softwarelisinsje of in domein.","also":["assets","asset"],"noTip":1},{"id":"capplan","g":"run","word":"Kapasiteitsplanning","text":"Soargje dat der genôch rekkenkrêft, opslach en minsken binne foar wat der oankomt.","also":["capacity plan","capacity planning"]},{"id":"scaling","g":"run","word":"Skalearring","text":"Mear brûkers oankinne troch in masine mear krêft te jaan (opskalearje) of mear masines ta te foegjen (útskalearje).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Bedriuwskontinuïteit","text":"Plannen om de wichtige dingen draaiende te hâlden as der wat grots mis giet, lykas it ferlies fan in kantoar, in kaaileveransier of de kompjûters.","also":["business continuity plan","business continuity"]},{"id":"dr","g":"run","word":"Rampherstel (DR)","text":"It plan en de helpmiddels om in tsjinst werom te krijen nei wat serieus, lykas it ferlies fan in hiel gegevenssintrum.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Hersteltiiddoel (RTO)","text":"De langste tiid dat in tsjinst nei in ramp del wêze mei foardat er wer wurkje moat.","also":["RTO"]},{"id":"rpo","g":"run","word":"Hersteldoel foar gegevens (RPO)","text":"Hoefolle resinte gegevens do ferlieze kinst sûnder dat it slim is, mjitten yn tiid. In RPO fan ien oere betsjut op syn minst elke oere in back-up.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundânsje","text":"Reserves klear hawwe, lykas in twadde tsjinner, sadat ien útfal de tsjinst net stopet.","also":["redundancy"]},{"id":"failover","g":"run","word":"Failover","text":"Sels oerskeakelje nei in reservesysteem as it gewoane útfalt.","also":["fail over"]},{"id":"spof","g":"run","word":"Inkeld mislearringspunt","text":"Ien ûnderdiel dat alles meineamt as it stikken giet, om’t der gjin reserve is.","also":["single points of failure","SPOF","single point of failure"]},{"id":"maintwin","g":"run","word":"Ûnderhâldsfinster","text":"In plande tiid dat in tsjinst foar ûnderhâld stilset of fertrage wurde mei, foarôf oan brûkers oankundige.","also":["maintenance windows","planned maintenance","maintenance window"]},{"id":"handover","g":"run","word":"Oerdracht","text":"Wurk, kennis en ferantwurdlikheid oerjaan oan in oare persoan of in oar team, sadat der neat tusken wâl en skip rekket.","also":["handovers","handover"]},{"id":"kb","g":"run","word":"Kennisbank","text":"In kolleksje help-artikels en antwurden, foar brûkers en foar it team.","also":["knowledge bases","knowledge base"]},{"id":"csat","g":"run","word":"Klanttefredenheid (CSAT)","text":"In sifer fan brûkers dat seit hoe tefreden se wiene, faak frege nei’t in fersyk ôfsluten is.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Leveransier","text":"In bûtenbedriuw dêr’t do op fertroust, lykas dyn hostingoanbieder. Ek wol vendor of tredde partij neamd.","also":["suppliers","vendor","vendors","third party","supplier"],"noTip":1},{"id":"retire","g":"run","word":"Tsjinst beëinigje","text":"In tsjinst foar goed en feilich útsette: de brûkers ynljochtsje, de gegevens en tagong ôfhannelje en de kosten stopje.","also":["retiring a service"]},{"id":"eol","g":"run","word":"Ein fan libben (EOL)","text":"As in produkt gjin fernijings of stipe mear fan syn makker krijt, sadat it ferfongen wurde moat.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cyberfeiligens","text":"Systemen en gegevens beskermje, sadat der net yn ynbrutsen wurdt en se net stellen of skansearre wurde.","also":["cyber security","cybersecurity"]},{"id":"authn","g":"sec","word":"Autentikaasje","text":"Kontrolearje wa’t immen is, meastal mei in wachtwurd of in koade. Faak ynkoarte ta authn.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Autorisaasje","text":"Kontrolearje wat immen dwaan mei as do witst wa’t er is. Faak ynkoarte ta authz.","also":["authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Multyfaktor-autentikaasje (MFA)","text":"Ynlogge mei twa of mear bewizen, lykas in wachtwurd plus in koade op dyn tillefoan. Ek wol twafaktor (2FA) neamd.","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Ien kear ynlogge om yn in protte systemen te kommen, lykas oeral dyn wurkaccount brûke.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Wachtwurdbehearder","text":"In app dy’t sterke wachtwurden makket en se foar dy ûnthâldt.","also":["password managers","password manager"]},{"id":"secret","g":"sec","word":"Geheim","text":"In wachtwurd, kaai of oare priveekoade dy’t in programma brûkt om yn wat te kommen. It moat nea dield of yn de koade skreaun wurde.","also":["secrets","secret"],"noTip":1},{"id":"apikey","g":"sec","word":"API-kaai","text":"In geheime koade wêrmei in programma de API fan in oare tsjinst brûke kin, en dy sjen lit wa’t it brûkt (en foar betellet).","also":["API keys","API key"]},{"id":"accesstoken","g":"sec","word":"Tagongstoken","text":"In tydlike tagongspas dy’t bewiist dat in programma der yn mei, sadat it net elke kear dyn wachtwurd nedich hat. Net itselde as in AI-token.","also":["access tokens","access token"]},{"id":"encryption","g":"sec","word":"Fersifering","text":"Ynformaasje trochinoar sette, sadat allinnich immen mei de goeie kaai it lêze kin.","also":["encrypted","encrypt","encryption"]},{"id":"https","g":"sec","word":"HTTPS","text":"De feilige wize wêrop websiden reizgje, sjen litten troch it slotsje yn dyn webblêder, sadat nimmen dertusken se lêze of feroarje kin."},{"id":"cert","g":"sec","word":"SSL/TLS-sertifikaat","text":"In digitale identiteitskaart wêrmei in webside bewize kin wa’t se is en HTTPS brûke kin. It ferrint, dus it moat fernijd wurde.","also":["TLS certificate","SSL certificate","certificate","certificates","sertifikaat"]},{"id":"permissions","g":"sec","word":"Tastimmingen","text":"De regels foar wa’t wat sjen of feroarje mei.","also":["permission","permissions"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Minste rjochten","text":"Eltse persoan of eltse programma allinnich de tagong jaan dy’t se echt nedich hawwe, en allinnich salang’t se it nedich hawwe.","also":["principle of least privilege","least privilege"]},{"id":"rbac","g":"sec","word":"Rolbasearre tagongskontrôle (RBAC)","text":"Tagong jaan op rol, lykas besjogger of bewurker, yn stee fan persoan foar persoan.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Kwetsberens","text":"In swak plak dat immen brûke koe om yn te brekken of skea te dwaan.","also":["vulnerabilities","vulnerability"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"In swak plak dat oanfallers kenne foardat de makkers der tiid foar hân hawwe om it te reparearjen.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Skealike software, lykas firussen, makke om skea te dwaan, te spionearjen of te stellen."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware dy’t dyn bestannen op slot docht en jild easket om se frij te litten. Goeie back-ups binne de bêste ferdigening.","also":["ransomware attack","gizelingssoftware"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Falske berjochten dy’t besykje dy te ferrifeljen om wachtwurden of jild fuort te jaan, of wat skealiks te iepenjen.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Sosjale manipulaasje","text":"Minsken ferrifelje, yn stee fan kompjûters, om tagong te krijen, lykas in falske oprop fan “IT-stipe”."},{"id":"firewall","g":"sec","word":"Firewall","text":"In wachter dy’t bepaalt hokker netwerkferkear binnenkomme of útgean mei.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Koart foar virtual private network: in privee, fersifere ferbining oer it ynternet, faak brûkt om feilich by wurksystemen te kommen.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Ferstoppingsoanfal (DoS, DDoS)","text":"In tsjinst oerstreame mei safolle falsk ferkear dat echte minsken it net brûke kinne. DDoS betsjut dat it fan in protte kompjûters tagelyk komt.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetraasjetest (pen test)","text":"Freonlike saakkundigen ynhiere om te besykjen yn te brekken, sadat swakke plakken fûn wurde foardat echte oanfallers se fine.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Feiligensaudit","text":"In soarchfâldige kontrôle fan hoe goed wat beskerme is, tsjin in list fan goede praktiken.","also":["security audits","security audit"]},{"id":"threatmodel","g":"sec","word":"Bedrigingsmodellearring","text":"Neitinke oer wa’t wat oanfalle koe, hoe, en wat do dwaan soest om se te stopjen.","also":["threat model","threat modeling","threat modelling"]},{"id":"breach","g":"sec","word":"Gegevenslek","text":"As privee-ynformaasje útkomt by minsken dy’t it net hawwe moatte, of ferlern giet of sûnder tastimming feroare wurdt.","also":["data breaches","data breach"]},{"id":"pii","g":"sec","word":"Persoanlike gegevens","text":"Alle ynformaasje oer in persoan dy’t identifisearre wurde kin, lykas in namme, e-mailadres of lokaasje. Ek wol PII neamd.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"AVG","text":"De Jeropeeske wet oer persoanlike gegevens (it Feriene Keninkryk hat in eigen ferzje): sammelje allinnich wat do nedich hast, hâld it feilich, en lit minsken harren gegevens sjen of wiskje.","also":["General Data Protection Regulation","GDPR"]},{"id":"dataprot","g":"sec","word":"Gegevensbeskerming","text":"Persoanlike gegevens goed en binnen de wet behannelje.","also":["data protection law","data protection"]},{"id":"privacypolicy","g":"sec","word":"Privacyferklearring","text":"In iepenbiere side dy’t seit hokker persoanlike gegevens do sammelest, wêrom, en wat do der mei dochst.","also":["privacy statement","privacy notice","privacy policy"]},{"id":"consent","g":"sec","word":"Tastimming","text":"In dúdlik, frij ja fan in persoan dat syn gegevens op in bepaalde wize brûkt wurde. Hy kin it op elk momint ynlûke.","also":["opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"In lyts bestân dat in webside yn dyn webblêder bewarret om dingen te ûnthâlden, lykas dat do ynlogd bist. Guon hawwe earst dyn tastimming nedich.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Gegevensminimalisaasje","text":"Allinnich de persoanlike gegevens sammelje en bewarje dy’t do echt nedich hast foar it wurk.","also":["data minimization","data minimisation"]},{"id":"retention","g":"sec","word":"Gegevensbewarring","text":"Hoe lang gegevens bewarre wurde foardat se wiske wurde. Se net langer bewarje as nedich is feiliger en faak wetlik ferplichte.","also":["retention period","data retention"]},{"id":"anon","g":"sec","word":"Anonimisearring","text":"Gegevens sa feroarje dat nimmen der ridlik mear út identifisearre wurde kin.","also":["anonymised","anonymization","anonymous data","anonimisearring"]},{"id":"pseudo","g":"sec","word":"Pseudonimisearring","text":"Nammen en oare details ferfange troch koades, mei in kaai apart bewarre om se wer te keppeljen. It binne noch altyd persoanlike gegevens.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Ferwurkersoerienkomst (DPA)","text":"In kontrakt dat seit hoe’t in leveransier út dyn namme mei persoanlike gegevens omgean mei.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Gegevensbeskermingseffektbeoardieling (DPIA)","text":"In soarchfâldige blik, foardat do begjinst, op hoe’t in plan om persoanlike gegevens te brûken minsken beynfloedzje kin en hoe’t de risiko’s ferlege wurde kinne.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Kontrôlelog","text":"In oersjoch fan wa’t wat die en wannear, sadat hannelingen letter kontrolearre wurde kinne.","also":["audit logs","audit trail","audit log"]},{"id":"compliance","g":"sec","word":"Compliance","text":"De wetten, regels en noarmen folgje dy’t foar dy jilde, en oantoane kinne dat do dat dochst.","also":["compliant","neilibjen fan regels"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"In bekende ynternasjonale noarm foar it behearen fan ynformaasjefeiligens. Bedriuwen kinne dêrop sertifisearre wurde.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"In Amerikaansk rapport, kontrolearre troch bûtenstiende kontrôleurs, dat sjen lit dat in bedriuw goed foar klantgegevens soarget.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agint","text":"In AI dy’t sels oan in taak wurket: de koade lêst, feroarings makket, kontrôles útfiert en ferslach docht. Syn wurk wurdt noch altyd kontrolearre.","also":["aginten"]},{"id":"token","g":"ai","word":"Token","text":"De lytse stikjes tekst dy’t in AI lêst en skriuwt, likernôch trijekwart fan in wurd elk. AI-gebrûk wurdt yn tokens teld, dus minder tokens litte mear oer fan dyn abonnemint.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"In lyts kommando dat op in bepaald momint sels rint, bygelyks as in AI-sesje begjint, sadat it team dyn opmerkings heart.","also":["hooks"]},{"id":"ai","g":"ai","word":"Keunstmjittige yntelliginsje (AI)","text":"Kompjûtersystemen dy’t dingen dogge dêr’t wy meastal tinke dat in persoan foar nedich is, lykas skriuwe, fragen beäntwurdzje of plaatsjes werkenne.","also":["AI","artificial intelligence","KI"],"noTip":1},{"id":"ml","g":"ai","word":"Masinelearen (ML)","text":"In manier om kompjûters patroanen leare te litten út in protte foarbylden, yn stee fan se krekte regels te jaan.","also":["machine learning","masinelearen"]},{"id":"model","g":"ai","word":"Model","text":"It oplate “brein” fan in AI-systeem, boud troch te learen fan enoarm folle foarbylden. Modellen ferskille yn feardigens, snelheid en priis.","also":["models","AI model","modellen"],"noTip":1},{"id":"llm","g":"ai","word":"Grut taalmodel (LLM)","text":"In AI-model oplaat op enoarm folle tekst, sadat it taal lêze en skriuwe kin.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI dy’t nije dingen makket, lykas tekst, plaatsjes of koade, yn stee fan se allinnich te sortearjen of te herkennen.","also":["GenAI","generative AI","generative KI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"In programma wêrmei do yn deistige taal praat, troch te typen of te sprekken.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Wat do in AI jouwst: dyn fraach of ynstruksjes, plus alles wat do him oerlangest. Dúdliker prompts krije meastal bettere antwurden.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt-ûntwerp","text":"De feardigens om prompts te skriuwen dy’t betroubere, nuttige resultaten jouwe.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Systeemprompt","text":"Eftergrûnynstruksjes dy’t in AI krijt foardat it petear begjint, dy’t syn rol en regels bepale. Se weagje swierder as wat do typst.","also":["system prompts","system instruction","system instructions","system prompt"]},{"id":"context","g":"ai","word":"Kontekst","text":"Alles wat de AI sjen kin wylst er wurket: de ynstruksjes, dyn berjochten, bestannen dy’t er lêzen hat en eardere antwurden.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontekstfinster","text":"Hoefolle in AI tagelyk yn gedachten hâlde kin, mjitten yn tokens. Dêrbûten falle âldere dielen ôf of wurde gearfette.","also":["context windows","context window"]},{"id":"session","g":"ai","word":"Sesje","text":"Ien wurkpetear mei in AI, fan begjin oant ein. In nije sesje begjint mei in farsk ûnthâld.","also":["sessions","session","sesjes"],"noTip":1},{"id":"memory","g":"ai","word":"Ûnthâld","text":"Notysjes dy’t in AI tusken sesjes hâldt, sadat er dyn foarkarren en eardere besluten ûnthâldt.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallusinaasje","text":"As in AI wat seit dat hiel wis klinkt, mar betocht of ferkeard is. Kontrolearje wichtige feiten.","also":["hallucinations","hallucinate","hallucinates","hallusinaasjes"]},{"id":"training","g":"ai","word":"Training","text":"In model leare troch it enoarm folle foarbylden te sjen, foardat immen it brûkt.","also":["trained","training"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Trainingsgegevens","text":"De foarbylden dêr’t in model fan learde. Syn kennis hâldt op by de datum dat dy gegevens sammele binne.","also":["training set","training data"]},{"id":"cutoff","g":"ai","word":"Kennisgrins","text":"De datum dat de ynboude kennis fan in AI ophâldt. It wit neat fan lettere dingen, útsein as it se opsiket.","also":["training cutoff","knowledge cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Ekstra training fan in besteand model op dyn eigen foarbylden, om it better te meitsjen yn ien bepaalde taak.","also":["fine-tune","fine-tuned","fine tuning","fynôfstimming"]},{"id":"inference","g":"ai","word":"Ynferinsje","text":"In AI-model dat echt brûkt wurdt om wat te beäntwurdzjen, yn tsjinstelling ta oplaat wurde.","also":["model inference","inference"]},{"id":"tooluse","g":"ai","word":"Arkgebrûk","text":"In AI dy’t dingen dwaan kin, net allinnich prate: kommando’s útfiere, bestannen lêze of op it web sykje, fia ark dy’t de app him jout.","also":["tool calling","tool call","tool calls","tool use"]},{"id":"subagent","g":"ai","word":"Subagint","text":"In helper-AI dêr’t in haad-AI in lytsere klus oan oerlit en it resultaat fan werom krijt.","also":["subagents","sub-agent","subagent"]},{"id":"multiagent","g":"ai","word":"Multy-agint","text":"Ferskate AI’s dy’t gearwurkje oan ien stik wurk, elk mei syn eigen part, as in lyts team.","also":["multi-agent system","multi-agent"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"Hoefolle in AI sels dwaan mei foardat er in persoan freegje moat.","also":["autonomous","autonomy","autonoom"]},{"id":"hitl","g":"ai","word":"Minske yn de lus","text":"In persoan belutsen hâlde om te kontrolearjen of goed te keuren wat de AI docht op wichtige mominten. Yn AI-gile bist dat do.","also":["human-in-the-loop","HITL","human in the loop"]},{"id":"guardrails","g":"ai","word":"Feiligenshekken","text":"Grinzen en kontrôles dy’t de aksjes fan in AI feilich hâlde, lykas goedkarring freegje foardat wat live giet. Se ferlytsje it risiko op flaters, mar slute se net út.","also":["guardrail","guardrails"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"In AI yn dyn eigen dokuminten litte neisjen foardat er antwurdet, sadat syn antwurden op dyn feiten rêste.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Tekst omsette yn in list getallen dy’t de betsjutting fêstlizze, sadat in kompjûter dingen fine kin dy’t wat likes betsjutte.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Fektordatabank","text":"In databank boud om dy listen getallen (embeddings) troch te sykjen, om materiaal mei in soartgelikense betsjutting te finen.","also":["vector databases","vector store","vector database","fektordatabanken"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"In mienskiplike manier om ark en gegevensboarnen oan AI-apps te keppeljen, sadat in AI se brûke kin.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatuer","text":"In ynstelling foar hoe aventoerlik de antwurden fan in AI binne. Leech jout stabiler, mear foarspelbere antwurden; heech jout mear ôfwikseling. Gjin fan beide soarget derfoar dat er altyd gelyk hat.","also":["model temperature","temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multymodaal","text":"Yn steat om mei mear as ien soarte ynformaasje te wurkjen, lykas tekst, plaatsjes en lûd.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Evaluaasje (eval)","text":"In plande test fan hoe goed in AI it docht op keazen foarbylden, sadat do modellen of prompts fergelykje kinst.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Foaroardiel","text":"As in AI (of in persoan) ûnearlik de iene kant op helt, faak troch wêr’t er fan learde.","also":["biased","bias"],"noTip":1},{"id":"responsible","g":"ai","word":"Ferantwurde AI","text":"AI earlik, feilich en iepen brûke, mei minsken dy’t noch altyd ferantwurdlik binne foar de resultaten.","also":["ethical AI","responsible AI"]},{"id":"injection","g":"ai","word":"Promptynjeksje","text":"In trúk wêrby’t ferburgen ynstruksjes yn in webside of bestân besykje in AI wat dwaan te litten dat syn brûker net frege hat.","also":["prompt injections","prompt injection"]},{"id":"ratelimit","g":"ai","word":"Fersykgrins","text":"In limyt op hoefolle fersiken do yn in fêste tiid nei in tsjinst stjoere meist. Giest der oerhinne, dan moatst wachtsje.","also":["rate limits","rate limited","rate limit"]},{"id":"usagelimit","g":"ai","word":"Gebrûksgrins","text":"Hoefolle AI-wurk dyn abonnemint yn in perioade talit, wêrnei’t it stopet of mear kostet.","also":["usage limits","usage limit"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Software foar it grutste part bouwe troch in AI te beskriuwen wat do wolst en him de koade skriuwe te litten.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budzjet","text":"It bedrach oan jild dat foar wat apart set is.","also":["budgets","budget"],"noTip":1},{"id":"costest","g":"money","word":"Kostenrame","text":"In gissing fan wat eat kostje sil, foardat do begjinst.","also":["cost estimates","cost estimate","kostenberekkening"]},{"id":"roi","g":"money","word":"Rendemint op ynvestearring (ROI)","text":"Wat do werom krijst yn ferliking mei wat do ynstutsen hast. As it posityf is, wie it it wurdich.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Totale eigenerskosten (TCO)","text":"Alles wat eat echt kostet oer syn hiele libben, net allinnich de keappriis: gebrûk, stipe, fernijings en úteinlik it útfasearjen.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx en OpEx","text":"CapEx is jild dat fan tefoaren útjûn wurdt oan dingen dy’t do hâldst; OpEx is trochrinnende útjeften, lykas moanlikse rekkens.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abonnemint","text":"Geregeld betelje, meastal moanliks of jierliks, om wat te kinnen brûke.","also":["subscriptions","subscription","abonneminten"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software dy’t do online brûkst en mei in abonnemint betellest, wylst de makker it foar dy rint.","also":["SaaS"]},{"id":"payg","g":"money","word":"Betelje nei gebrûk","text":"Allinnich betelje foar wat do brûkst, lykas wolktsjinsten of AI-tokens.","also":["pay-as-you-go","usage-based pricing","pay as you go"]},{"id":"overage","g":"money","word":"Oerskriding","text":"Gebrûk boppe wat dyn abonnemint omfettet, wat ekstra kostje kin.","also":["overages","overage charges","overage"]},{"id":"billingalert","g":"money","word":"Faktuerwarskôging","text":"In berjocht as de útjeften of it gebrûk in nivo berikke dat do keazen hast. It warskôget dy, mar stopet net altyd fierdere kosten.","also":["billing alerts","spending alert","billing alert"]},{"id":"freetier","g":"money","word":"Fergees nivo","text":"In fergees nivo fan in betelle tsjinst, mei grinzen. Handich om mei te begjinnen.","also":["free plan","free tier"]},{"id":"pricing","g":"money","word":"Prizeplan","text":"De ferskillende pakketten dy’t in tsjinst ferkeapet, elk mei in eigen priis en grinzen.","also":["pricing plans","price plan","pricing plan"]},{"id":"licence","g":"money","word":"Lisinsje","text":"De regels foar hoe do wat in oar makke hat brûke, kopiearje, feroarje of diele meist, lykas software, lettertypen of plaatsjes.","also":["licences","license","licenses","licence","lisinsjes"],"noTip":1},{"id":"opensource","g":"money","word":"Iepen boarne","text":"Software wêrfan elkenien de koade lêze, brûke en faak fergees feroarje kin, ûnder de regels fan de lisinsje.","also":["open-source","open source software","OSS","open source"]},{"id":"osslicence","g":"money","word":"Iepenboarne-lisinsje","text":"De regels dy’t by iepenboarne-koade hearre. Guon litte hast alles ta (lykas MIT); guon freegje dy ek dyn feroarings te dielen (lykas GPL).","also":["open source licences","MIT licence","GPL","open source licence"]},{"id":"proprietary","g":"money","word":"Proprietêr","text":"Eigendom fan in bedriuw en net frij te kopiearjen of te feroarjen. It tsjinoerstelde fan iepen boarne.","also":["proprietary software","proprietary","proprietêr"]},{"id":"copyright","g":"money","word":"Auteursrjocht","text":"It wetlike rjocht fan in makker om kopyen fan syn wurk te kontrolearjen, ek koade en tekst.","also":["copyrighted","copyright"],"noTip":1},{"id":"ip","g":"money","word":"Yntellektuele eigendom (IP)","text":"Ideeën en makkingen dy’t de wet as eigendom beskôget, lykas koade, ûntwerpen, nammen en logo’s.","also":["intellectual property","IP"]},{"id":"tos","g":"money","word":"Gebrûksbetingsten","text":"De regels dêr’t do mei ynstimst as do in tsjinst brûkst.","also":["terms and conditions","terms of use","terms of service"]},{"id":"contract","g":"money","word":"Kontrakt","text":"In skriftlike oerienkomst tusken twa kanten dy’t de wet stipet.","also":["contracts","contract"],"noTip":1},{"id":"sow","g":"money","word":"Wurkbeskriuwing (SOW)","text":"In dokumint dat krekt útset hokker wurk dien wurdt, foar wannear en foar hoefolle.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Fêste priis","text":"In ôfpraat priis foar de hiele klus, hoe lang it ek duorret.","also":["fixed-price","fixed price"]},{"id":"tm","g":"money","word":"Tiid en materiaal","text":"Betelje foar de oeren dy’t echt wurke binne en de dingen dy’t echt brûkt binne, yn stee fan in fêste priis.","also":["T&M","time and materials"]},{"id":"invoice","g":"money","word":"Faktuer","text":"In rekken dy’t om betelling freget foar dien wurk of levere guod.","also":["invoices","invoice"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"As fuortgean fan in leveransier sa dreech of djoer is dat do mei him fêstsitst.","also":["lock-in","fêstsitte by in leveransier"]},{"id":"procurement","g":"money","word":"Ynkeap","text":"It proses fan leveransiers kieze en by har keapje.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Tsjinstkredyt","text":"Jild werom of koarting dy’t do krijst as in leveransier syn SLA net hellet.","also":["service credits","service credit"]}]}};
